window.RECOEVO = {"codigos":[{"id":"MEZ","nombre":"Todo va en la misma bolsa","dim":"D1","def":"El participante describe que en su hogar o local los residuos orgánicos se mezclan con el resto (una sola bolsa/caneca, 'todo es un revoltijo')."},{"id":"SEP","nombre":"Separación parcial","dim":"D1","def":"Separa algún material (plástico, botellas, papel) o reconoce separar a medias; también afirmaciones de que la gente en general no separa."},{"id":"APR","nombre":"Ya aprovechan lo orgánico","dim":"D1","def":"Uso informal actual de residuos orgánicos: sobras a perros o animales (conejos, pollos, gallinas), cáscaras a las matas, abono casero, regalar sobrantes del fruver."},{"id":"PUN","nombre":"El shut y las esquinas","dim":"D2","def":"Disposición en espacio público: basura fuera del shut/chute, esquinas, botaderos, sacar la bolsa a destiempo, niños que la arrastran."},{"id":"RUT","nombre":"El carro no cumple","dim":"D2","def":"Servicio de recolección: horarios irregulares, no pasa, pasa 'de afán', diferencia con zonas residenciales, cobro de la tarifa."},{"id":"ROM","nombre":"Rompen las bolsas","dim":"D2","def":"Recicladores, habitantes de calle o perros abren y riegan las bolsas."},{"id":"FAU","nombre":"Perros, ratas y plagas","dim":"D3","def":"Fauna y plagas asociadas: perros callejeros/abandonados, ratas, ratones, zancudos, cucarachas, pulgas, palomas."},{"id":"AMB","nombre":"Viento, olor, barro y salud","dim":"D3","def":"Efectos ambientales y de salud: olor, viento que dispersa papeles, lluvia y barro, afectación respiratoria, riesgo de caídas, suciedad en el local."},{"id":"SEG","nombre":"Inseguridad","dim":"D3","def":"Relación entre basura/puntos de acopio y delincuencia, consumo o vigilancia de locales."},{"id":"CUL","nombre":"Cultura y hábito","dim":"D4","def":"Atribución del problema a la cultura, pereza, desorden, falta de conciencia o de tiempo ('mantenemos a las carreras')."},{"id":"EST","nombre":"Estado ausente","dim":"D4","def":"Abandono institucional: alcaldía ausente, sin control ni multas efectivas, peticiones sin respuesta, políticos clientelistas."},{"id":"FRE","nombre":"¿Y si los demás no?","dim":"D4","def":"Barreras de acción colectiva: 'qué hacemos tres si diez no lo hacen', miedo a parecer loco, falta de empuje, la solución se demora."},{"id":"COM","nombre":"Líderes y comunidad","dim":"D5","def":"Tejido comunitario disponible: juntas de acción comunal, asambleas, líderes, iniciativas propias (imagen de la Virgen, huertas con colegios, corrales)."},{"id":"EDU","nombre":"Campaña y pedagogía","dim":"D5","def":"Propuestas de sensibilización: campañas, volantes, pósteres, TikTok/YouTube, capacitaciones, ejemplo propio, visitas."},{"id":"ART","nombre":"Sí a la caneca/artefacto","dim":"D5","def":"Aceptación o valoración de una caneca exclusiva o dispositivo para orgánicos; condiciones de uso (que sea práctico, que recojan)."},{"id":"INC","nombre":"Nada es gratis","dim":"D5","def":"Incentivos, compensaciones o costos: remuneración, regalar la caneca, 'no hay nada que no tenga uno que ofrecer'."},{"id":"AGR","nombre":"Del campo al abono","dim":"D5","def":"Conexión con el campo y el abono: compost valorado, recuerdos rurales, crítica a los químicos, abono caro/importado, uso de fertilizantes."}],"dimensiones":[{"id":"D1","nombre":"Cómo se maneja hoy","color":"#7CFFB2"},{"id":"D2","nombre":"Dónde se rompe el sistema","color":"#FF6B6B"},{"id":"D3","nombre":"Impactos que se sienten","color":"#FFB547"},{"id":"D4","nombre":"Por qué no cambia","color":"#B79CFF"},{"id":"D5","nombre":"Qué haría funcionar la solución","color":"#5CC8FF"}],"escalas":{"satisfaccion":{"nombre":"Satisfacción con la situación actual de residuos","anclas":{"1":"Muy insatisfecho: queja fuerte, indignación, 'es un desorden tenaz'","2":"Insatisfecho: describe problema con molestia","3":"Neutral o ambivalente: describe sin juicio o con matices","4":"Satisfecho: considera que funciona aceptablemente","5":"Muy satisfecho: valora positivamente la situación"},"na":"No aplica cuando la unidad no evalúa la situación (p. ej., datos demográficos o propuestas)"},"disposicion":{"nombre":"Disposición a participar en la solución","anclas":{"1":"Rechazo: no lo haría / no sirve","2":"Escéptico: duda fuerte, 'la gente no lo va a hacer'","3":"Condicionado: sí, pero solo si… (incentivo, recolección, que otros lo hagan)","4":"Favorable: le parece buena idea","5":"Entusiasta/comprometido: se ofrece, propone, lidera"},"na":"No aplica cuando la unidad no habla de soluciones o cambio"}},"participantes":{"E01":{"rol":"Hogar","detalle":"Residente de la parte alta, saca la basura de su casa","audios":["Audio1"]},"E02":{"rol":"Comercio · líder","detalle":"Comerciante y líder comunal","audios":["Audio2","Audio3"]},"E03":{"rol":"Hogar · líder","detalle":"Líder comunitario del barrio","audios":["Audio4"]},"E04":{"rol":"Comercio de alimentos","detalle":"Trabajador de fruver","audios":["Audio5"]},"E05":{"rol":"Comercio + hogar","detalle":"Comerciante; también vive en la zona","audios":["Audio6","Audio10"]},"E06":{"rol":"Hogar","detalle":"Residente adulto mayor","audios":["Audio7"]},"E07":{"rol":"Hogar + comercio","detalle":"Residente joven; atiende un comercio","audios":["Audio8"]},"E08":{"rol":"Comercio","detalle":"Comerciante; vive en otra zona","audios":["Audio9"]}},"saturacion":[10.05,14.0,15.64,16.42,16.81,16.96,17.0,17.0],"acuerdo":{"n_unidades":220,"kappa_global":0.695,"acuerdo_global":0.969,"kappa_medio_por_codigo":0.694,"kappa_pond_satisfaccion":0.735,"kappa_pond_disposicion":0.68},"validacion":[{"audio":"Audio1","similitud":0.961,"duracion":458},{"audio":"Audio2","similitud":0.899,"duracion":26},{"audio":"Audio3","similitud":0.948,"duracion":520},{"audio":"Audio4","similitud":0.923,"duracion":501},{"audio":"Audio5","similitud":0.939,"duracion":360},{"audio":"Audio6","similitud":0.825,"duracion":387},{"audio":"Audio7","similitud":0.831,"duracion":257},{"audio":"Audio8","similitud":0.971,"duracion":568},{"audio":"Audio9","similitud":0.911,"duracion":798},{"audio":"Audio10","similitud":0.742,"duracion":90}],"units":[{"id":"A1-T03-1","p":"E01","a":"Audio1","t":33.4,"q":"Listo. [E01], muy buenas tardes. Mi nombre es Willington Javier Ortiz, soy profesor del Politécnico Grancolombiano y quiero hacerle unas preguntas frente a la forma como usted y su familia están haciendo disposición de la comida. Normalmente a eso lo llamamos los residuos orgánicos. Nosotros nos hemos dado cuenta de que en esta zona, y prácticamente en gran parte de Bogotá, el manejo de las basuras se convirtió en un problema. Y esto no es un problema de ahora, es un problema de hace mucho tiempo. ¿Qué opina usted de eso?","o":"Claro que sí, señor. Buenas tardes. Sí, lo que está diciendo usted es totalmente real: el problema de las basuras es crónico y, entre más días, como que se va poniendo peor el asunto. El manejo que nosotros le damos a las basuras es lo más normal.","e":"Claro que sí, señor. Buenas tardes. Lo que está diciendo usted es totalmente real: el problema de las basuras es crónico y, entre más días, como que se va poniendo peor el asunto. El manejo que nosotros le damos a las basuras es lo más normal.","c":[],"s":1,"d":null,"k":[],"n":"problema crónico y cada vez peor"},{"id":"A1-T03-2","p":"E01","a":"Audio1","t":50.9,"q":"Listo. [E01], muy buenas tardes. Mi nombre es Willington Javier Ortiz, soy profesor del Politécnico Grancolombiano y quiero hacerle unas preguntas frente a la forma como usted y su familia están haciendo disposición de la comida. Normalmente a eso lo llamamos los residuos orgánicos. Nosotros nos hemos dado cuenta de que en esta zona, y prácticamente en gran parte de Bogotá, el manejo de las basuras se convirtió en un problema. Y esto no es un problema de ahora, es un problema de hace mucho tiempo. ¿Qué opina usted de eso?","o":"De pronto tampoco soy de las personas que vamos a aportar diciendo, o en esta entrevista voy a decir: \"No, es que nosotros lo hacemos, lo seleccionamos\", porque eso es una cosa totalmente falsa en mi caso.","e":"De pronto tampoco soy de las personas que vamos a aportar diciendo en esta entrevista: “No, es que nosotros lo hacemos, lo seleccionamos”, porque eso es una cosa totalmente falsa en mi caso.","c":["MEZ","SEP"],"s":null,"d":null,"k":[],"n":"autocrítica: en su casa no separa"},{"id":"A1-T03-3","p":"E01","a":"Audio1","t":61.8,"q":"Listo. [E01], muy buenas tardes. Mi nombre es Willington Javier Ortiz, soy profesor del Politécnico Grancolombiano y quiero hacerle unas preguntas frente a la forma como usted y su familia están haciendo disposición de la comida. Normalmente a eso lo llamamos los residuos orgánicos. Nosotros nos hemos dado cuenta de que en esta zona, y prácticamente en gran parte de Bogotá, el manejo de las basuras se convirtió en un problema. Y esto no es un problema de ahora, es un problema de hace mucho tiempo. ¿Qué opina usted de eso?","o":"Entonces, sí, sería bueno que hubiera como un poquitico más de cultura en esa situación y que fuéramos un poquito más dejuiciosos para beneficio de nosotros y de la gran mayoría de personas que de pronto seamos perjudicados con el tema de las basuras, sí señor.","e":"Entonces sí, sería bueno que hubiera un poquitico más de cultura en esa situación y que fuéramos un poquito más juiciosos, para beneficio de nosotros y de la gran mayoría de personas que de pronto somos perjudicados con el tema de las basuras.","c":["CUL"],"s":null,"d":null,"k":[],"n":""},{"id":"A1-T05-1","p":"E01","a":"Audio1","t":101.4,"q":"Usted habla de una palabra clave, y es la cultura. La cultura es lo que nos hace hacer lo que siempre hacemos. ¿Cómo cree usted que debe cambiar esa cultura, o cómo podemos hacer para que cambie esa cultura para mejorar un poco esa forma de manejar los residuos, sobre todo los residuos de alimentos?","o":"Sí, de pronto diría yo que se me ocurre criticar capacitaciones, pero como la gran mayoría de personas, hablando aquí del sector del sur de Bogotá, somos personas que mantenemos esas las carreras.","e":"De pronto se me ocurren capacitaciones, pero la gran mayoría de personas, hablando aquí del sur de Bogotá, somos personas que mantenemos a las carreras.","c":["CUL"],"s":null,"d":null,"k":[],"n":"\"mantenemos a las carreras\""},{"id":"A1-T05-2","p":"E01","a":"Audio1","t":115.8,"q":"Usted habla de una palabra clave, y es la cultura. La cultura es lo que nos hace hacer lo que siempre hacemos. ¿Cómo cree usted que debe cambiar esa cultura, o cómo podemos hacer para que cambie esa cultura para mejorar un poco esa forma de manejar los residuos, sobre todo los residuos de alimentos?","o":"Entonces uno de pronto no va a decir: \"No, yo sí voy a seleccionar\", porque sería muy bueno, sería muy bueno, sería chévere que uno tomara esa buena costumbre como uno cepillarse los dientes o hacer tantas cosas que son básicas, que meterlo uno en el menú también de lo básico, poder uno hacer eso.","e":"Entonces uno de pronto no va a decir: \"No, yo sí voy a seleccionar\", porque sería muy bueno, sería chévere que uno tomara esa buena costumbre como uno cepillarse los dientes o hacer tantas cosas que son básicas; meterlo uno en el menú también de lo básico, poder uno hacer eso.","c":["CUL"],"s":null,"d":3,"k":[],"n":"separar sería bueno, pero no es costumbre"},{"id":"A1-T05-3","p":"E01","a":"Audio1","t":132.4,"q":"Usted habla de una palabra clave, y es la cultura. La cultura es lo que nos hace hacer lo que siempre hacemos. ¿Cómo cree usted que debe cambiar esa cultura, o cómo podemos hacer para que cambie esa cultura para mejorar un poco esa forma de manejar los residuos, sobre todo los residuos de alimentos?","o":"Pero como generalmente mantenemos esas las carreras, entonces uno que la cáscara de la papa a la misma bolsa, que el cartón, que esto, que las cáscaras de huevo, todo es un revoltijo.","e":"Pero generalmente mantenemos las carreras en una misma bolsa las cáscaras de la papa, el cartón, las cáscaras de huevo, todo es un revoltijo.","c":["MEZ","CUL"],"s":null,"d":null,"k":[],"n":"todo es un revoltijo"},{"id":"A1-T05-4","p":"E01","a":"Audio1","t":144.0,"q":"Usted habla de una palabra clave, y es la cultura. La cultura es lo que nos hace hacer lo que siempre hacemos. ¿Cómo cree usted que debe cambiar esa cultura, o cómo podemos hacer para que cambie esa cultura para mejorar un poco esa forma de manejar los residuos, sobre todo los residuos de alimentos?","o":"Pero sí, la pregunta está buena y me parece mágico que existiera algo donde uno pudiera depositar todo y que la misma máquina como que seleccionara y dijera uno: \"Puedo botar esto tranquilo\", o vienen y le recogen acá y se acabó el problema. Y lo práctico para uno también sería chévere.","e":"Pero sí, la pregunta está buena y me parece mágico que existiera algo donde uno pudiera depositar todo y que la misma máquina dijera: \"Puedo botar esto tranquilo\", o vienen y le recogen acá y se acabó el problema. Y lo práctico para uno también sería chévere.","c":["ART"],"s":null,"d":5,"k":["recoleccion","practico"],"n":"\"me parece mágico\"; que recojan"},{"id":"A1-T13-1","p":"E01","a":"Audio1","t":196.1,"q":"Pregunta: ¿Usted tiene un bote de basura exclusivo en la cocina o hay uno para todos?","o":"No, hay uno en la cocina y en los baños hay especialmente para ellos. Sino que al sacarlo, como todo, en la bolsa negra todo se amarra y...","e":"No, hay uno en la cocina y en los baños hay especialmente para ellos. Al sacarlo, como todo, en la bolsa negra se amarra todo.","c":["MEZ"],"s":null,"d":null,"k":[],"n":"todo en la bolsa negra"},{"id":"A1-T15-1","p":"E01","a":"Audio1","t":231.9,"q":"Usted prácticamente ya sugirió una solución, una solución que creo que fue comentada por su propio hijo. Entonces, en ese sentido, ¿usted cree que la gente de este sector sí estaría dispuesta a hacer uso eficiente de ese artefacto para manejar exclusivamente los residuos de alimentos?","o":"Pues yo pienso que la persona que nos interese el medio ambiente, uno se compromete. Se compromete uno y de pronto al ver que está funcionando en algunas otras partes, de pronto del sector, pienso yo que con seguridad la gente puede hacer ese gran aporte. Sería práctico, sería muy bueno, sería buenísimo eso.","e":"Yo pienso que a la persona que le interese el medio ambiente, uno se compromete. Se compromete uno y, al ver que está funcionando en otras partes del sector, pienso que con seguridad la gente puede hacer ese gran aporte. Sería práctico, sería muy bueno, sería buenísimo.","c":["ART","FRE"],"s":null,"d":4,"k":["ejemplo"],"n":"se compromete al ver que funciona en otras partes"},{"id":"A1-T15-2","p":"E01","a":"Audio1","t":251.7,"q":"Usted prácticamente ya sugirió una solución, una solución que creo que fue comentada por su propio hijo. Entonces, en ese sentido, ¿usted cree que la gente de este sector sí estaría dispuesta a hacer uso eficiente de ese artefacto para manejar exclusivamente los residuos de alimentos?","o":"Entonces yo creo que sí.","e":"Entonces yo creo que sí.","c":["ART"],"s":null,"d":4,"k":[],"n":""},{"id":"A1-T17-1","p":"E01","a":"Audio1","t":261.7,"q":"¿Y usted haría eso, es decir, disponer los residuos de alimentos en esa caneca sin nada a cambio?","o":"Yo creo que no hay nada que no tenga uno que ofrecer algo, bien sea la disponibilidad de tiempo o que tenga un costo económico. Entonces sí tiene que haber algún costo o algo que se deba hacer para poder adquirir ese tipo de beneficio.","e":"Yo creo que no hay nada en que uno no tenga que ofrecer algo, bien sea disponibilidad de tiempo o un costo económico. Entonces sí tiene que haber algún costo o algo que se deba hacer para poder adquirir ese tipo de beneficio.","c":["INC"],"s":null,"d":3,"k":["costo"],"n":"acepta aportar tiempo o dinero"},{"id":"A1-T19-1","p":"E01","a":"Audio1","t":284.7,"q":"¿Usted cree que usted y los de su comunidad están sufriendo realmente por el tema de las basuras?","o":"Uy, totalmente, totalmente. Aquí, afortunadamente, nosotros yo vivo en la parte de arriba del sector, que allá la gran mayoría de personas sí tiene la facilidad de bajar las basuras aquí al Chuck.","e":"Uy, totalmente. Aquí, afortunadamente, yo vivo en la parte de arriba del sector, y allá la gran mayoría de personas sí tiene la facilidad de bajar las basuras aquí al shut.","c":["PUN"],"s":null,"d":null,"k":[],"n":""},{"id":"A1-T19-2","p":"E01","a":"Audio1","t":301.2,"q":"¿Usted cree que usted y los de su comunidad están sufriendo realmente por el tema de las basuras?","o":"Pero resulta que aquí en el Chuck hay un desorden tenaz porque de pronto mandan los niños o personas que como nosotros los colombianos somos tan cómodos, nos parece gracia aguolearla así y que se riegue y salgo corriendo y me subo en el bus y chao.","e":"Pero resulta que aquí en el shut hay un desorden tenaz, porque de pronto mandan a los niños, o personas que, como nosotros los colombianos somos tan cómodos, nos parece gracia tirarla así y que se riegue, y salgo corriendo, me subo en el bus y chao.","c":["PUN","CUL"],"s":1,"d":null,"k":[],"n":"desorden tenaz en el shut"},{"id":"A1-T19-3","p":"E01","a":"Audio1","t":314.0,"q":"¿Usted cree que usted y los de su comunidad están sufriendo realmente por el tema de las basuras?","o":"No nos importa que de pronto el vecino salga, un niño pise una cáscara de papa, de banano y se caiga, no nos importa. O sea, eso es tan sencillo como eso.","e":"No nos importa que de pronto el vecino salga y un niño pise una cáscara de papa o de banano y se caiga. No nos importa. Eso es tan sencillo como eso.","c":["AMB","CUL"],"s":1,"d":null,"k":[],"n":"riesgo de caídas"},{"id":"A1-T19-4","p":"E01","a":"Audio1","t":325.3,"q":"¿Usted cree que usted y los de su comunidad están sufriendo realmente por el tema de las basuras?","o":"También sería bueno que existiera un poquitico de concientización en cuanto a hacer el depósito de la basura en el sitio adecuado el día adecuado, o si no es el día adecuado, por algo llama Chuck, está disponible para tirarlo allá. Pero entonces con la de la manera que corresponde.","e":"También sería bueno que existiera un poquitico de concientización en cuanto a hacer el depósito de la basura en el sitio adecuado el día adecuado; si no es el día adecuado, por algo llama shut, está disponible para tirarlo allá. Pero entonces con la manera que corresponde.","c":["EDU","PUN"],"s":null,"d":4,"k":["pedagogia"],"n":"concientización"},{"id":"A1-T23-1","p":"E01","a":"Audio1","t":365.1,"q":"En algunas partes sucede que después de que la gente saca la basura para que el camión la recoja, entre ese tiempo de disponer la basura y que el camión la recoja, normalmente pasan recicladores que riegan absolutamente todo. ¿Aquí pasa también eso?","o":"Uy, aquí es donde hay menos control. Al menos por allá en ciertas partes de Bogotá, más hacia el norte, al menos el guarda de seguridad está pendiente de sacar la basura precisamente cuando el camión va a pasar.","e":"Uy, aquí es donde hay menos control. En ciertas partes de Bogotá, más hacia el norte, por lo menos el guarda de seguridad está pendiente de sacar la basura precisamente cuando el camión va a pasar.","c":["EST","PUN"],"s":2,"d":null,"k":[],"n":"menos control que en el norte"},{"id":"A1-T23-2","p":"E01","a":"Audio1","t":378.1,"q":"En algunas partes sucede que después de que la gente saca la basura para que el camión la recoja, entre ese tiempo de disponer la basura y que el camión la recoja, normalmente pasan recicladores que riegan absolutamente todo. ¿Aquí pasa también eso?","o":"Acá no, acá es al contrario, porque si uno le dice a algún vecino: \"¿Qué está haciendo ahí, hermano? Le encargo\", lo tratan a uno a lo colombiano.","e":"Aquí no, aquí es al contrario, porque si uno le dice a algún vecino: “¿Qué está haciendo ahí, hermano? Le encargo”, lo tratan a uno a lo colombiano.","c":["FRE"],"s":2,"d":null,"k":[],"n":"si uno reclama, lo tratan mal"},{"id":"A1-T25-1","p":"E01","a":"Audio1","t":391.5,"q":"¿El camión pasa los días y a la hora que debe pasar?","o":"Mire que acá más bien descontroladito la hora de la pasada del camión. Hay veces pasa por la mañana, pero él pasa haciendo bulla, él pasa pitando. Pero sí es bastante descontroladito el horario del paso del carro recolector de basuras.","e":"Acá está más bien descontroladito el horario del camión. Hay veces que pasa por la mañana; pasa haciendo bulla, pasa pitando. Pero sí es bastante descontroladito el horario del carro recolector de basuras.","c":["RUT"],"s":2,"d":null,"k":[],"n":"horario descontrolado"},{"id":"A1-T27-1","p":"E01","a":"Audio1","t":413.0,"q":"Veo muchos perros. Cuando hay acumulación de basura, yo me imagino que los perros a todo momento están tratando de escarbar también esa basura.","o":"Sí, sí, incluso suena gracioso lo que le voy a decir, pero incluso los perros lo ven a uno bajar con la basura y ellos se quedan como mirando: \"¿Le trae algo ahí?\", y se le tiran a uno como a tirar encima, a raparle la bolsita.","e":"Sí, incluso suena gracioso lo que le voy a decir, pero incluso los perros lo ven a uno bajar con la basura y ellos se quedan como mirando: “¿Le trae algo ahí?”, y se le tiran a uno como a tirar encima, a raparle la bolsita.","c":["FAU","ROM"],"s":2,"d":null,"k":[],"n":"perros se lanzan a la bolsa"},{"id":"A1-T27-2","p":"E01","a":"Audio1","t":423.0,"q":"Veo muchos perros. Cuando hay acumulación de basura, yo me imagino que los perros a todo momento están tratando de escarbar también esa basura.","o":"Entonces, pues imagínese usted ya el desorden que hay.","e":"Entonces, imagínese usted el desorden que hay.","c":["FAU"],"s":1,"d":null,"k":[],"n":""},{"id":"A1-T29-1","p":"E01","a":"Audio1","t":429.1,"q":"Aparte de perros, ¿plagas asociadas a eso?","o":"Hay ratas y hay ratones también. Lo dije en doble sentido.","e":"Hay ratas y también ratones. Lo dije en doble sentido.","c":["FAU"],"s":2,"d":null,"k":[],"n":"ratas y ratones"},{"id":"A1-T31-1","p":"E01","a":"Audio1","t":432.9,"q":"¿Ratas o más?","o":"Sí, sí, sí, esos son los de más cuidado. Sí, mucha plaga, zancudito, cuando hace así como solecito se levanta mucho zancudito, mucha los ratoncitos salen también a tomar el sol, salen de ahí de debajo de la basura.","e":"Sí, esos son los de más cuidado. Mucha plaga: zancudito; cuando hace solecito se levanta mucho zancudito, y los ratoncitos salen también a tomar el sol, salen de debajo de la basura.","c":["FAU","AMB"],"s":1,"d":null,"k":[],"n":"zancudos, ratones bajo la basura"},{"id":"A2-T06-1","p":"E02","a":"Audio2","t":10.6,"q":"¿Y siempre ha visto el mismo problema de basuras?","o":"Siempre ha visto.","e":"Siempre lo ha visto.","c":[],"s":2,"d":null,"k":[],"n":"siempre ha habido problema"},{"id":"A2-T08-1","p":"E02","a":"Audio2","t":15.5,"q":"¿Ha mejorado o empeorado?","o":"Trató de mejorar cuando empezaron a recoger, porque antes nunca nos cobraban, pero no nos la recogían. Sí, sí, ahí anda. ¿Me das un helado, por favor?","e":"Trató de mejorar cuando empezaron a recoger, porque antes nunca nos cobraban, pero no nos la recogían.","c":["RUT"],"s":3,"d":null,"k":[],"n":"mejoró un poco cuando empezaron a recoger"},{"id":"A3-T06-1","p":"E02","a":"Audio3","t":35.4,"q":"Ah, ok, perfecto. Hablemos de las basuras, pero no de todas las basuras, sino las que se llaman residuos orgánicos, las que salen de la cocina. La gente normalmente...","o":"No, nadie las separa. Nadie las separa, botan ahí y los perros vuelven a eso. Nosotros teníamos con puertas ahí y los muchachos que reciclar, ellos vienen... Cuando está con candado rompen la puerta, abren y empiezan a... Sacan las bolsas, riegan la basura, se llevan la bolsa y se llevan lo que es reciclado.","e":"No, nadie las separa. Botan ahí y los perros vuelven a eso. Nosotros teníamos [el shut] con puertas y los muchachos que reciclan vienen; cuando está con candado, rompen la puerta, abren, sacan las bolsas, riegan la basura y se llevan lo que es reciclable.","c":["SEP","FAU","ROM"],"s":1,"d":null,"k":[],"n":"rompen el candado del shut"},{"id":"A3-T06-2","p":"E02","a":"Audio3","t":59.3,"q":"Ah, ok, perfecto. Hablemos de las basuras, pero no de todas las basuras, sino las que se llaman residuos orgánicos, las que salen de la cocina. La gente normalmente...","o":"En sí lo orgánico nadie, es que ni nosotros lo hacemos.","e":"Lo orgánico, en sí, nadie [lo separa]; es que ni nosotros lo hacemos.","c":["MEZ","SEP"],"s":null,"d":null,"k":[],"n":"ni nosotros lo hacemos"},{"id":"A3-T08-1","p":"E02","a":"Audio3","t":73.0,"q":"¿Usted cree que si la gente comenzara a separar lo orgánico del resto de basuras, eso podría mejorar un poco?","o":"Es una cultura que se puede demorar 100 años, porque la gente es...","e":"Es una cultura que se puede demorar 100 años, porque la gente es...","c":["CUL","FRE"],"s":null,"d":2,"k":[],"n":"cultura de 100 años"},{"id":"A3-T08-2","p":"E02","a":"Audio3","t":78.9,"q":"¿Usted cree que si la gente comenzara a separar lo orgánico del resto de basuras, eso podría mejorar un poco?","o":"Es que la gente está, esa vaina ahí, se vienen por la mañana, yo a las 3 de la mañana ya estoy por la ventana echando chisme y se vienen, suben con la bolsa y ven el bus y no alcanzan a llegar allá, la botan ahí, mandan a un niño con unas bolsas ni las berrejas que no la pueden ni cargar, la traen arrastrándose, la rompen por el camino y ahí queda.","e":"Es que la gente está, esa vaina ahí, se vienen por la mañana; yo a las 3 de la mañana ya estoy por la ventana echando chisme y se vienen, suben con la bolsa y no alcanzan a llegar allá, la botan ahí, mandan a un niño con unas bolsas ni las berrejas que no la pueden ni cargar, la traen arrastrándose, la rompen por el camino y ahí queda.","c":["PUN","CUL"],"s":1,"d":null,"k":[],"n":"niños arrastran la bolsa"},{"id":"A3-T08-3","p":"E02","a":"Audio3","t":103.6,"q":"¿Usted cree que si la gente comenzara a separar lo orgánico del resto de basuras, eso podría mejorar un poco?","o":"La tejan por ahí. La cultura es difícil.","e":"La dejan por ahí. La cultura es difícil.","c":["CUL"],"s":null,"d":2,"k":[],"n":""},{"id":"A3-T10-1","p":"E02","a":"Audio3","t":113.9,"q":"¿Habrá algo para cambiar esa cultura? ¿O ya nos fuimos así?","o":"Pues la vaina es que colocan ese... Que dice que hay que multa, no sé cuántos salarios mínimos, pero ¿quién vigila eso? Nadie. Ni policía hay por ahí vigilando.","e":"La vaina es que colocan ese [aviso] que dice que hay multa de no sé cuántos salarios mínimos, pero ¿quién vigila eso? Nadie. Ni policía hay por ahí vigilando.","c":["EST"],"s":1,"d":null,"k":[],"n":"multas sin vigilancia"},{"id":"A3-T12-1","p":"E02","a":"Audio3","t":123.5,"q":"¿Ah?","o":"Ni policía por ahí vigilando. No, ellos vienen a las ollas a cobrar el impuesto. Eso no sirve para nada. Yo no los puedo ver.","e":"Ni policía por ahí vigilando. No, ellos vienen a las ollas a cobrar el impuesto. Eso no sirve para nada. Yo no los puedo ver.","c":["EST"],"s":1,"d":null,"k":[],"n":""},{"id":"A3-T14-1","p":"E02","a":"Audio3","t":153.1,"q":"¿Qué pasaría si uno le dijera a varias familias: le doy una caneca especial solo para la basura que sale de la cocina (residuos orgánicos), con el ánimo de que no los mezcle con papeles de baño y otro tipo de basuras?","o":"Se puede hacer, pero es que la cultura es difícil si no hay una persona que recoja todos los días esa basura es difícil porque ellos la revuelven y si la hubiera...","e":"Se puede hacer, pero es que la cultura es difícil si no hay una persona que recoja todos los días esa basura; es difícil porque ellos la revuelven y si la hubiera...","c":["ART","CUL"],"s":null,"d":3,"k":["recoleccion"],"n":"se puede si alguien recoge a diario"},{"id":"A3-T16-1","p":"E02","a":"Audio3","t":181.4,"q":"Pues ya si hay el carro que va a pasar todos los días recogiendo la basura. Porque usted sabe que esa basura que sale de la cocina, es decir, los residuos orgánicos, sirven para hacer compost en los cultivos.","o":"Claro. Díganmelo a mí, crecí en el campo. Nosotros ya recogíamos todo eso para echarle a las plantas.","e":"Claro. Díganmelo a mí, que crecí en el campo. Nosotros ya recogíamos todo eso para echarle a las plantas.","c":["AGR"],"s":null,"d":null,"k":[],"n":"crecí en el campo (recuerdo, no práctica actual)"},{"id":"A3-T18-1","p":"E02","a":"Audio3","t":214.7,"q":"Porque nosotros, usted que sabe del campo, nosotros hemos identificado otro problema... ¿Qué vale? 10, 15. ¿Y aquí hay cultivos en el campo?","o":"Sí, claro. Pero usted sabe que cada vez se necesita más abono agroquímicos para que...","e":"Sí, claro. Pero usted sabe que cada vez se necesita más abono agroquímico para que…","c":["AGR"],"s":null,"d":null,"k":[],"n":"cada vez más agroquímicos"},{"id":"A3-T20-1","p":"E02","a":"Audio3","t":226.2,"q":"¿Los cultivos de...?","o":"Sí, la vaina es esa. Lo químico. Le dicen lo químico y eso enferma a la gente.","e":"Sí, la vaina es esa: lo químico. Le dicen lo químico, y eso enferma a la gente.","c":["AGR"],"s":null,"d":null,"k":[],"n":"lo químico enferma"},{"id":"A3-T22-1","p":"E02","a":"Audio3","t":240.3,"q":"Total. Usted sabe que lo químico es químico. Nosotros nos criaron con el abono que nos echamos a las plantas. Era la caca de la vaca.","o":"De acuerdo. Seca, la desboronamos con la mano y se la echamos a las plantas. Esos eran cultivos de la verraquera. Siga su versión. Perdón.","e":"De acuerdo. [La boñiga] seca, la desboronábamos con la mano y se la echábamos a las plantas. Esos eran cultivos de la berraquera.","c":["AGR"],"s":null,"d":null,"k":[],"n":"abono de vaca, cultivos de la verraquera"},{"id":"A3-T24-1","p":"E02","a":"Audio3","t":248.2,"q":"Tranquilo.","o":"Perdón que la sacaron de ahí. Pero aquí, como le digo, culturizar a la gente...","e":"Pero aquí, como le digo, culturizar a la gente…","c":["CUL"],"s":null,"d":2,"k":[],"n":""},{"id":"A3-T26-1","p":"E02","a":"Audio3","t":285.8,"q":"Nosotros tenemos una idea y es organizar una comunidad para que la mayor cantidad de personas seleccionen los residuos de la cocina, lo que es orgánico, recogerlo y justamente con eso hacer compost. Con eso evitamos que mucha gente que siembra no utilice químicos. Porque eso a la larga nos está afectando. ¿Qué opinan ustedes de esa idea?","o":"Pues la idea es, esa idea es, pero... Es difícil para mí, es difícil por un lado, las juntas de acción comunal es una cosa casi móvil. Yo no sé qué pasa.","e":"La idea es buena, pero… es difícil para mí. Por un lado, las juntas de acción comunal son una cosa casi móvil. Yo no sé qué pasa.","c":["COM","FRE"],"s":null,"d":3,"k":[],"n":"la JAC es inestable"},{"id":"A3-T28-1","p":"E02","a":"Audio3","t":307.5,"q":"¿Aquí hay juntas de acción comunal?","o":"Claro, yo fui líder comunal, he sido líder comunal desde que estoy aquí hace 36 años. Yo estuve directamente en las juntas, ya soy líder comunal, pero por lo que sé, por lo que conozco, pero entonces es difícil. Eso que es, si lo piensan hacer, es...","e":"Claro, yo fui líder comunal; he sido líder comunal desde que estoy aquí hace 36 años. Yo estuve directamente en las juntas, ya soy líder comunal, pero por lo que sé, por lo que conozco, entonces es difícil. Eso que es, si lo piensan hacer, es...","c":["COM"],"s":null,"d":null,"k":[],"n":"líder comunal 36 años"},{"id":"A3-T28-2","p":"E02","a":"Audio3","t":328.0,"q":"¿Aquí hay juntas de acción comunal?","o":"Cada barrio tiene su junta de acción comunal, cada barrio tiene su salón comunal. Les tocaría hacer una jornada, venir y en una asamblea. Por ejemplo, mañana, a la una de la tarde de todos, aquí hay asamblea en el salón comunal de Villarrocita. Mañana. Ahí es donde se vive.","e":"Cada barrio tiene su junta de acción comunal, cada barrio tiene su salón comunal. Les tocaría hacer una jornada, venir y en una asamblea. Mañana a la una de la tarde aquí hay asamblea en el salón comunal de Villarrocita. Ahí es donde se vive.","c":["COM"],"s":null,"d":4,"k":["lideres"],"n":"asamblea en el salón comunal"},{"id":"A3-T30-1","p":"E02","a":"Audio3","t":350.1,"q":"Sí, mañana puede...","o":"le pide permiso a la presidenta, le dice que necesita hablarle algo a la gente y usted lo habla. Ahí se puede empezar, al menos por la de Villarrocita. Que la gente empiece a...","e":"Le pide permiso a la presidenta, le dice que necesita hablarle algo a la gente y usted lo habla. Ahí se puede empezar, al menos por la [junta] de Villa Rosita. Que la gente empiece a…","c":["COM"],"s":null,"d":4,"k":["lideres"],"n":"pedir la palabra a la presidenta"},{"id":"A3-T32-1","p":"E02","a":"Audio3","t":387.9,"q":"Si yo le explico a su merced esta idea, ¿usted sería capaz de recoger todos los residuos de la cocina, la comida, solo y exclusivamente solo, para poder activar este programa? ¿Y usted cree que sus vecinas lo harían?","o":"Pues toca hablarles, irles hablando y la idea es que ustedes pasen también porque si uno dice ¡ay, se viene loco! eso es lo que van a decir ¡ay, el vecino se volvió loco!","e":"Pues toca hablarles, irles hablando y la idea es que ustedes pasen también; porque si uno dice “¡ay, se viene loco!”, eso es lo que van a decir: “¡ay, el vecino se volvió loco!","c":["FRE","EDU"],"s":null,"d":4,"k":["pedagogia"],"n":"que ustedes pasen; \"el vecino se volvió loco\""},{"id":"A3-T32-2","p":"E02","a":"Audio3","t":400.6,"q":"Si yo le explico a su merced esta idea, ¿usted sería capaz de recoger todos los residuos de la cocina, la comida, solo y exclusivamente solo, para poder activar este programa? ¿Y usted cree que sus vecinas lo harían?","o":"la idea es que sí traigan volanticos y empiecen a llamar la atención de la gente porque aquí sí, ella hace su bolsita de lo de la cocina pero como se amarra y se echa dentro de la otra bolsa y se va para allá...","e":"La idea es que sí traigan volanticos y empiecen a llamar la atención de la gente, porque aquí ella hace su bolsita de lo de la cocina, pero se amarra, se echa dentro de la otra bolsa y se va para allá…","c":["EDU","MEZ"],"s":null,"d":4,"k":["pedagogia"],"n":"volanticos"},{"id":"A3-T32-3","p":"E02","a":"Audio3","t":415.3,"q":"Si yo le explico a su merced esta idea, ¿usted sería capaz de recoger todos los residuos de la cocina, la comida, solo y exclusivamente solo, para poder activar este programa? ¿Y usted cree que sus vecinas lo harían?","o":"Entonces por el olor de la cocina, los perros, hay más perros que gente acá en el sector.","e":"Entonces, por el olor de la cocina, los perros, hay más perros que gente acá en el sector.","c":["FAU","AMB"],"s":1,"d":null,"k":[],"n":"más perros que gente"},{"id":"A3-T34-1","p":"E02","a":"Audio3","t":430.1,"q":"¿Qué otra plaga hay? Aparte, o sea, que ratas...","o":"Horarios viciosos, pero muy poco. No, no, no, pero animales. Cucarachas se ve. Pues donde hay desaseo, ratón. Pero así, cucaracha. Hace muchos años sufrimos por las pulgas. Pero ahora no sé, no volvieron.","e":"Viciosos, pero muy poco. Animales: se ven cucarachas; donde hay desaseo, ratón. Hace muchos años sufrimos por las pulgas, pero ahora no volvieron.","c":["FAU"],"s":3,"d":null,"k":[],"n":"cucarachas, ratones, poco"},{"id":"A3-T34-2","p":"E02","a":"Audio3","t":447.8,"q":"¿Qué otra plaga hay? Aparte, o sea, que ratas...","o":"O sea, yo, que aquí en la casa bastante sufrimos con los animales y ya, de un momento a otro, ni más. Creo que nos picaron y se murieron todas.","e":"Yo, que aquí en la casa bastante sufrimos con los animales y ya, de un momento a otro, ni más. Creo que nos picaron y se murieron todas.","c":["FAU"],"s":null,"d":null,"k":[],"n":"pulgas en su casa (pasado)"},{"id":"A3-T36-1","p":"E02","a":"Audio3","t":469.9,"q":"[E02], una última pregunta. ¿Usted cree que sí es posible llegar a hacer este cambio en esta localidad en especial?","o":"Pues, no es en la localidad, porque... Nosotros somos la localidad quinta de Usme. Grande, ¿no? Aproximadamente 200 barrios. La idea es que nosotros aquí de pronto se puede, por lo que estamos abandonados por la alcaldía. Aquí es muy poco lo que llegan cosas de la alcaldía.","e":"No es [toda] la localidad, porque somos la localidad quinta, Usme, grande: aproximadamente 200 barrios. La idea es que aquí de pronto se puede, porque estamos abandonados por la alcaldía. Aquí es muy poco lo que llega de la alcaldía.","c":["EST"],"s":1,"d":3,"k":[],"n":"abandonados por la alcaldía; \"de pronto se puede\""},{"id":"A3-T36-2","p":"E02","a":"Audio3","t":489.3,"q":"[E02], una última pregunta. ¿Usted cree que sí es posible llegar a hacer este cambio en esta localidad en especial?","o":"Ellos trabajan allá, para los barrios de allá. Los políticos que hay allá, ellos ya tienen sus barrios donde todo el mundo vota por ellos, por el tamal y no les interesan los otros.","e":"Ellos trabajan allá, para los barrios de allá. Los políticos que hay allá, ya tienen sus barrios donde todo el mundo vota por ellos, por el tamal, y no les interesan los otros.","c":["EST"],"s":1,"d":null,"k":[],"n":"clientelismo"},{"id":"A4-T02-2","p":"E03","a":"Audio4","t":29.6,"q":"[E03], buenas tardes. ¿Usted cuánto tiempo lleva viviendo aquí en el barrio?","o":"Yo tengo ya 50 años de estar aquí en el barrio. Yo tengo fotografías de todo esto cuando era potrero, todo esto de aquí para allá. De la iglesia cuando empezó a ser. Tenemos tres libros hechos por la madre [nombre omitido] de la comunidad. y varias cosas que se han hecho en el barrio.","e":"Yo tengo ya 50 años de estar aquí en el barrio. Tengo fotografías de todo esto cuando era potrero, de aquí para allá, y de la iglesia cuando empezó. Tenemos tres libros hechos por la madre [nombre omitido] sobre la comunidad y varias cosas que se han hecho en el barrio.","c":["COM"],"s":null,"d":null,"k":[],"n":"50 años, memoria del barrio"},{"id":"A4-T02-3","p":"E03","a":"Audio4","t":55.4,"q":"[E03], buenas tardes. ¿Usted cuánto tiempo lleva viviendo aquí en el barrio?","o":"Otra de los vivos tiempos que tengo yo aquí, a la parte de aquí abajo, tenemos hecho varias casas que construimos con compañeros. Hicimos varias casas para la madre [nombre omitido]. Y fuera de lo que le hemos hecho aquí al barrio, la iglesia, el comedor comunitario...","e":"Otro de los recuerdos que tengo aquí, en la parte de abajo: hicimos varias casas que construimos con compañeros para la madre [nombre omitido]. Y fuera de lo que le hemos hecho al barrio: la iglesia, el comedor comunitario…","c":["COM"],"s":null,"d":null,"k":[],"n":""},{"id":"A4-T04-1","p":"E03","a":"Audio4","t":95.0,"q":"[E02], con el tema del comedor comunitario, usted cree, hablando de orgánicos y basuras, que es lo que genera como tal los comedores, todo lo que es comercio, las personas, ¿usted considera que ha habido una buena gestión de basuras?","o":"No. Siempre se ha luchado contra el asunto de las basuras, sobre todo de esos botaderos así. Incluso yo hace poco limpiaron ese pedazo ahí y yo puse esa imagen de la Virgen del Carmen a ver si lo respetaban como aquel otro punto.","e":"No. Siempre se ha luchado contra el asunto de las basuras, sobre todo de esos botaderos así. Incluso hace poco limpiaron ese pedazo ahí y yo puse esa imagen de la Virgen del Carmen a ver si lo respetaban como en aquel otro punto.","c":["PUN","COM"],"s":2,"d":5,"k":[],"n":"puso la Virgen del Carmen contra el botadero"},{"id":"A4-T04-2","p":"E03","a":"Audio4","t":112.4,"q":"[E02], con el tema del comedor comunitario, usted cree, hablando de orgánicos y basuras, que es lo que genera como tal los comedores, todo lo que es comercio, las personas, ¿usted considera que ha habido una buena gestión de basuras?","o":"que es otro punto también, lo hice yo con la intolerancia de la gente, que mataba a la gente sin necesidad, los niños, las mujeres, muchas cosas que hubieron, han habido aquí en el barrio, ¿me entiendes? Pero en el asunto de las basuras ha sido duro. ¿Por qué?","e":"Que es otro punto también, lo hice yo por la intolerancia de la gente, que mataba a la gente sin necesidad, los niños, las mujeres, muchas cosas que han habido aquí en el barrio, ¿me entiendes? Pero en el asunto de las basuras ha sido duro. ¿Por qué?","c":["COM","SEG"],"s":2,"d":null,"k":[],"n":""},{"id":"A4-T04-3","p":"E03","a":"Audio4","t":131.4,"q":"[E02], con el tema del comedor comunitario, usted cree, hablando de orgánicos y basuras, que es lo que genera como tal los comedores, todo lo que es comercio, las personas, ¿usted considera que ha habido una buena gestión de basuras?","o":"Porque la misma comunidad no se presta, la misma comunidad no coge en un sitio. También es cierto que si hubiera, es que ese es el detalle, que si hubiera un sitio exclusivo para botar la basura, la gente la botaría, pero la gente muchas veces es perezosa.","e":"Porque la misma comunidad no se presta, no la deja en un solo sitio. También es cierto que si hubiera un sitio exclusivo para botar la basura, la gente la botaría, pero la gente muchas veces es perezosa.","c":["CUL","PUN","FRE"],"s":2,"d":3,"k":["practico"],"n":"si hubiera un sitio exclusivo, la gente lo usaría"},{"id":"A4-T04-4","p":"E03","a":"Audio4","t":148.0,"q":"[E02], con el tema del comedor comunitario, usted cree, hablando de orgánicos y basuras, que es lo que genera como tal los comedores, todo lo que es comercio, las personas, ¿usted considera que ha habido una buena gestión de basuras?","o":"o vienen de la casa con la bolsa y la riegan por ahí en las esquinas. En cualquier parte van descargando la basura. El asunto es que la basura se extiende y se riega en el barrio sencillamente por los perros. Los perros se encargan de romper bolsas. Hoy en día, ¿saben qué?","e":"Vienen de la casa con la bolsa y la riegan por ahí en las esquinas. En cualquier parte van descargando la basura. El asunto es que la basura se extiende y se riega en el barrio sencillamente por los perros. Los perros se encargan de romper bolsas. Hoy en día, ¿saben qué?","c":["PUN","ROM","FAU"],"s":1,"d":null,"k":[],"n":""},{"id":"A4-T04-5","p":"E03","a":"Audio4","t":166.2,"q":"[E02], con el tema del comedor comunitario, usted cree, hablando de orgánicos y basuras, que es lo que genera como tal los comedores, todo lo que es comercio, las personas, ¿usted considera que ha habido una buena gestión de basuras?","o":"Cada perro ya no pelea en el mismo puesto donde está la basura. Cada uno coge una bolsa y se abre para un punto.","e":"Cada perro ya no pelea en el mismo puesto donde está la basura: cada uno coge una bolsa y se abre para un punto.","c":["ROM","FAU"],"s":1,"d":null,"k":[],"n":"cada perro coge una bolsa"},{"id":"A4-T06-1","p":"E03","a":"Audio4","t":null,"q":"¿Usted cree que ese comportamiento de la gente de dejar la basura en cualquier lugar puede cambiar, se puede mejorar?","o":"Sí.","e":"Sí.","c":[],"s":null,"d":4,"k":[],"n":"sí puede cambiar"},{"id":"A4-T08-1","p":"E03","a":"Audio4","t":188.0,"q":"¿Cómo?","o":"Aquí yo tengo varios compañeros que hemos hablado sobre ese asunto para enseñarle a la gente y enseñarle a reciclar. Pero es que la gente aquí no, aquí los que reciclan son los viciosos. ¿Por qué? Porque ellos necesitan para su bicha, para su traba, para lo de ellos.","e":"Aquí yo tengo varios compañeros que hemos hablado sobre ese asunto para enseñarle a la gente y enseñarle a reciclar. Pero es que la gente aquí no, aquí los que reciclan son los viciosos. ¿Por qué? Porque ellos necesitan para su bicha, para su traba, para lo de ellos.","c":["EDU","COM","ROM"],"s":2,"d":4,"k":["lideres"],"n":"con compañeros enseñan a reciclar"},{"id":"A4-T08-2","p":"E03","a":"Audio4","t":207.4,"q":"¿Cómo?","o":"Pero no, muchas veces nosotros les decimos: \"No rompan las bolsas, compadre. Abran las bolsas, analicen y dejen eso ahí quieto para no regarlas\". Ellos a veces llevan la idea, comprenden sobre las cosas, porque aquí hay hartos muchachos que se rebuscan con el reciclaje. No muchachos, ancianos. Señoras mayores.","e":"Pero no, muchas veces nosotros les decimos: “No rompan las bolsas, compadre. Abran las bolsas, analicen y dejen eso ahí quieto para no regarlas”. Ellos a veces llevan la idea, comprenden sobre las cosas, porque aquí hay hartos muchachos que se rebuscan con el reciclaje. No, muchachos, son ancianos. Señoras mayores.","c":["ROM","COM"],"s":2,"d":4,"k":[],"n":"\"no rompan las bolsas\""},{"id":"A4-T10-1","p":"E03","a":"Audio4","t":234.8,"q":"¿Qué cree que es una buena solución respecto al tema de basuras?","o":"Sobre una solución sobre ese tema de basuras tocaría hacer una buena campaña para poner y concientizar a la gente, concientizar a la gente para que no hagamos esos regueros que tenemos que hacer en el barrio.","e":"Como solución al tema de basuras, tocaría hacer una buena campaña para concientizar a la gente, para que no hagamos esos regueros que hacemos en el barrio.","c":["EDU"],"s":null,"d":4,"k":["pedagogia"],"n":"campaña para concientizar"},{"id":"A4-T10-2","p":"E03","a":"Audio4","t":250.3,"q":"¿Qué cree que es una buena solución respecto al tema de basuras?","o":"Es como allí están haciendo el monumento ese para hacer el aviso de bienvenida al barrio, que es ese aviso que está allá.","e":"Es como allí, que están haciendo el monumento para el aviso de bienvenida al barrio, ese aviso que está allá.","c":["COM"],"s":null,"d":null,"k":[],"n":""},{"id":"A4-T10-3","p":"E03","a":"Audio4","t":260.7,"q":"¿Qué cree que es una buena solución respecto al tema de basuras?","o":"Es más, yo he pensado en encuadrar y quitar esa imagen de ahí, porque siempre la han respetado y sin embargo yo me pongo a rabiar por el botadero de basura, porque es que la gente es inconsciente.","e":"Es más, yo he pensado en encuadrar y quitar esa imagen de ahí, porque siempre la han respetado y sin embargo yo me pongo a rabiar por el botadero de basura, porque la gente es inconsciente.","c":["PUN","CUL"],"s":1,"d":null,"k":[],"n":"\"me pongo a rabiar\""},{"id":"A4-T12-1","p":"E03","a":"Audio4","t":287.5,"q":"Una pregunta, ¿su merced cómo administra su basura? ¿Usted la separa o cómo usted opera?","o":"Bueno, sí, yo recojo lo que son las botellas y muchas veces le pasa medio bulto o las que tengan en el momento cuando pasen los chinos o cuando pasen las señoras que muchas veces reciclan.","e":"Bueno, sí, yo recojo las botellas y muchas veces le paso medio bulto, o las que tenga en el momento, a los chinos o a las señoras que reciclan cuando pasan.","c":["SEP"],"s":null,"d":null,"k":[],"n":"pasa botellas a recicladores"},{"id":"A4-T12-2","p":"E03","a":"Audio4","t":300.2,"q":"Una pregunta, ¿su merced cómo administra su basura? ¿Usted la separa o cómo usted opera?","o":"Eso es para las personas mayores así, personas adultas tienen que estar reciclando, entonces ellos reciclan eso y uno les pasa la botella. ¿Yo para qué guardo botellas ahí? ¿Para qué, si yo no reciclo? Tengo mi casa, vivo bien, bendito sea mi Dios.","e":"Eso es para las personas mayores así, las personas adultas tienen que estar reciclando, entonces ellos reciclan eso y uno les pasa la botella. ¿Yo para qué guardo botellas ahí? ¿Para qué, si yo no reciclo? Tengo mi casa, vivo bien, bendito sea mi Dios.","c":["SEP"],"s":null,"d":null,"k":[],"n":""},{"id":"A4-T12-3","p":"E03","a":"Audio4","t":317.1,"q":"Una pregunta, ¿su merced cómo administra su basura? ¿Usted la separa o cómo usted opera?","o":"Pero sí he estado en el barrio en muchas cosas, muchas cosas. He estado con Dipron, he estado con varias aquí sobre el barrio. No me he metido de presidente de la Junta aquí porque es que hay mucha gente egoísta. Yo era una de las personas que colaboraba y me iba para las empresas.","e":"Pero sí he estado en el barrio en muchas cosas. He estado con Dipron y con varias [organizaciones] aquí en el barrio. No me he metido de presidente de la Junta porque hay mucha gente egoísta. Yo era una de las personas que colaboraba y me iba para las empresas.","c":["COM","FRE"],"s":null,"d":null,"k":[],"n":"gente egoísta en la Junta"},{"id":"A4-T12-4","p":"E03","a":"Audio4","t":338.8,"q":"Una pregunta, ¿su merced cómo administra su basura? ¿Usted la separa o cómo usted opera?","o":"Una empresa y alma bendita con las demás, conseguíamos lo que eran los regalos de los niños, los mercados para la gente pobre.","e":"Con una empresa y almas benditas, conseguíamos los regalos de los niños y los mercados para la gente pobre.","c":["COM"],"s":null,"d":null,"k":[],"n":""},{"id":"A4-T14-1","p":"E03","a":"Audio4","t":387.1,"q":"¿Usted cree que sería posible buscar una solución rápida al tema de basuras? ¿O cree que se demoraría?","o":"Se demoraría un poco. Yo sigo... Aquí viene uno de los amigos. Le presento a su amistad. ¿Qué más, viejo? Viene a encamellarla. Listo, listo. Él es otro de esos. Viene a encamellar. Trabaja con mármol y esa vaina.","e":"Se demoraría un poco. Yo sigo... Aquí viene uno de los amigos. Le presento a su amistad. ¿Qué más, viejo? Viene a encamellarla. Listo, listo. Él es otro de esos. Trabaja con mármol y esa vaina.","c":["FRE"],"s":null,"d":3,"k":[],"n":"se demoraría"},{"id":"A4-T14-2","p":"E03","a":"Audio4","t":409.9,"q":"¿Usted cree que sería posible buscar una solución rápida al tema de basuras? ¿O cree que se demoraría?","o":"Con ese nos hemos puesto, hay otros que tengo dos, tres que hemos estado a ver cómo hacemos, cómo le enseñamos a la gente a reciclar lo que es... Es más, hemos pensado en tener el asunto de corrales, de meter unas gallinas, de meter pollos, meter eso, ¿por qué?","e":"Con él y con otros dos o tres hemos estado viendo cómo le enseñamos a la gente a reciclar. Es más, hemos pensado en tener corrales, meter unas gallinas, meter pollos. ¿Por qué?","c":["COM","EDU"],"s":null,"d":5,"k":[],"n":"idea de corrales con gallinas (intención, no práctica)"},{"id":"A4-T14-3","p":"E03","a":"Audio4","t":429.0,"q":"¿Usted cree que sería posible buscar una solución rápida al tema de basuras? ¿O cree que se demoraría?","o":"Porque lo que sobra de la comida es lo que va a sobrar...","e":"Porque lo que sobra de la comida es lo que va a sobrar...","c":["COM"],"s":null,"d":5,"k":[],"n":"para lo que sobra de la comida"},{"id":"A4-T16-1","p":"E03","a":"Audio4","t":457.0,"q":"Pues sobre eso queremos hacerle una pregunta. Nosotros tenemos un proyecto, ¿qué opina usted de ese proyecto? y es darle aquí a las personas una caneca especial solo para los residuos de la cocina, lo que se llama residuo orgánico, porque eso sirve justamente para hacer compost, de hecho para muchos de los cultivos de por aquí cerca. ¿Está de acuerdo? ¿Qué opina de esa idea?","o":"Esa es la otra, que yo también he jodido con lo que son las siembras. Yo a los niños, a todo eso los he enseñado cómo sembrar.","e":"Esa es la otra, que yo también he jodido con las siembras. A los niños y a todo eso les he enseñado cómo sembrar.","c":["AGR","COM"],"s":null,"d":4,"k":[],"n":"enseña a sembrar"},{"id":"A4-T16-2","p":"E03","a":"Audio4","t":467.7,"q":"Pues sobre eso queremos hacerle una pregunta. Nosotros tenemos un proyecto, ¿qué opina usted de ese proyecto? y es darle aquí a las personas una caneca especial solo para los residuos de la cocina, lo que se llama residuo orgánico, porque eso sirve justamente para hacer compost, de hecho para muchos de los cultivos de por aquí cerca. ¿Está de acuerdo? ¿Qué opina de esa idea?","o":"He tenido aquí, incluso yo personalmente he tenido colegios aquí que vienen y les enseñan cómo se siembra una mata, para qué sirve esta mata, qué es esto, la lechuga, repollo, acelga, espinaca, todo eso. Tuve mi sembrado ahí, pero entonces muchas veces hay gente que, ay hermano, eso... Entonces echa uno al suelo.","e":"He tenido aquí, incluso yo personalmente he tenido colegios aquí que vienen y les enseñan cómo se siembra una mata, para qué sirve esta mata, qué es esto, la lechuga, repollo, acelga, espinaca, todo eso. Tuve mi sembrado ahí, pero entonces muchas veces hay gente que, ay hermano, eso... Entonces uno echa al suelo.","c":["AGR","COM","FRE"],"s":null,"d":4,"k":[],"n":"huerta con colegios"},{"id":"A4-T16-3","p":"E03","a":"Audio4","t":490.4,"q":"Pues sobre eso queremos hacerle una pregunta. Nosotros tenemos un proyecto, ¿qué opina usted de ese proyecto? y es darle aquí a las personas una caneca especial solo para los residuos de la cocina, lo que se llama residuo orgánico, porque eso sirve justamente para hacer compost, de hecho para muchos de los cultivos de por aquí cerca. ¿Está de acuerdo? ¿Qué opina de esa idea?","o":"¿Por qué? Porque no hay un empuje. Si le dieren un empuje y vuelven: \"Ti, ti, ti, ti, venga, hagamos esto, hagamos lo otro\"...","e":"¿Por qué? Porque no hay un empuje. Si le dieran un empuje: “venga, hagamos esto, hagamos lo otro”…","c":["FRE"],"s":null,"d":3,"k":[],"n":"no hay un empuje"},{"id":"A5-T06-1","p":"E04","a":"Audio5","t":39.5,"q":"¿Qué hacen ustedes o cómo están manejando justamente lo que se considera ya residuo, lo que es ya no de uso? Basura, basura pero orgánica.","o":"Nosotros cogemos unas canecas y lo que hacemos es que hay varias gentes...","e":"Nosotros cogemos unas canecas, y lo que hacemos es que hay varias personas…","c":["APR"],"s":null,"d":null,"k":[],"n":"guardan canecas"},{"id":"A5-T08-1","p":"E04","a":"Audio5","t":47.6,"q":"¿Hay picadito?","o":"No. Viene gente y así se las lleva, por ejemplo, para los conejos, para los pollos. Entonces les guardan una canequita y ellos traen la de ellos o una bolsita y se las llevan. O sea, a la larga eso no se pierde.","e":"No. Viene gente y así se las lleva, para los conejos, para los pollos. Entonces les guardan una canequita y ellos traen la de ellos o una bolsita y se las llevan. A la larga eso no se pierde.","c":["APR"],"s":null,"d":null,"k":[],"n":"se las llevan para conejos y pollos"},{"id":"A5-T10-1","p":"E04","a":"Audio5","t":59.7,"q":"No, no, no.","o":"Hay un otro uso. No, la desperdicia no va directamente a Chux, sino viene personas y se las llevan.","e":"Hay otro uso. El desperdicio no va directamente al shut, sino que vienen personas y se lo llevan.","c":["APR"],"s":null,"d":null,"k":[],"n":"no va al shut"},{"id":"A5-T12-2","p":"E04","a":"Audio5","t":80.5,"q":"¿Hay alguna reglamentación que los obliga por alguna razón a ustedes los fruveros a hacer eso, digamos que a no botarla en cualquier parte, sino a disponerla con un tercero, o eso no existe?","o":"como es como manejo ya de la conciencia de uno, porque sabiendo que le sirve a otra persona, entonces uno no, es como si yo no me como un pan duro, pero de pronto un indigente sí viene y le da el pancito y se lo come con un pintico, entonces eso ya...","e":"Como es cómo manejo ya la conciencia de uno, porque sabiendo que le sirve a otra persona, entonces uno no, es como si yo no me como un pan duro, pero de pronto un indigente sí viene y le da el pancito y se lo come con un pintico, entonces eso ya...","c":["APR"],"s":null,"d":null,"k":[],"n":"\"le sirve a otra persona\""},{"id":"A5-T12-3","p":"E04","a":"Audio5","t":101.9,"q":"¿Hay alguna reglamentación que los obliga por alguna razón a ustedes los fruveros a hacer eso, digamos que a no botarla en cualquier parte, sino a disponerla con un tercero, o eso no existe?","o":"es como decisión de uno.","e":"Es una decisión de uno.","c":["APR"],"s":null,"d":null,"k":[],"n":""},{"id":"A5-T14-1","p":"E04","a":"Audio5","t":106.5,"q":"¿Hay problemas de basura aquí en el barrio?","o":"Sí, claro que sí.","e":"Sí, claro.","c":[],"s":2,"d":null,"k":[],"n":"sí hay problemas de basura"},{"id":"A5-T16-1","p":"E04","a":"Audio5","t":110.4,"q":"¿Por qué cree usted que se da esos problemas?","o":"No, porque la gente no cuida, la gente es muy desorganizada, la gente no cuida, simplemente no cuida y allá hay un chux y tiran la basura ahí.","e":"Porque la gente no cuida, la gente es muy desorganizada, simplemente no cuida. Allá hay un shut y tiran la basura ahí.","c":["CUL","PUN"],"s":1,"d":null,"k":[],"n":"la gente no cuida"},{"id":"A5-T18-1","p":"E04","a":"Audio5","t":121.3,"q":"¿Por fuera?","o":"Por fuera del chux.","e":"Por fuera del shut.","c":["PUN"],"s":2,"d":null,"k":[],"n":"por fuera del shut"},{"id":"A5-T20-1","p":"E04","a":"Audio5","t":129.7,"q":"¿Usted cree que eso puede cambiar? ¿Qué tendríamos que hacer para que la gente cambie la forma?","o":"Primeramente cambiar uno y hacerle como entender a la gente que el cambio empieza por uno y si la gente ve que uno bota la basura por dentro de ellos, pues me imagino que hará lo mismo como para que sientan conciencia de ellos de que eso está bien.","e":"Primero, cambiar uno y hacerle entender a la gente que el cambio empieza por uno. Si la gente ve que uno bota la basura adentro [del shut], me imagino que hará lo mismo, para que tomen conciencia de que eso está bien.","c":["EDU"],"s":null,"d":4,"k":["ejemplo"],"n":"el cambio empieza por uno"},{"id":"A5-T22-1","p":"E04","a":"Audio5","t":153.7,"q":"¿Usted cree que la gente separa diferentes tipos de residuos o la mezcla toda y la va a usar como llega?","o":"No, así como llega, así como la botan, ellos no separan.","e":"No, así como llega, así la botan, ellos no separan.","c":["SEP"],"s":2,"d":null,"k":[],"n":"la gente no separa"},{"id":"A5-T24-1","p":"E04","a":"Audio5","t":193.5,"q":"¿Usted que trabaja con frutas y verduras cree que la gente debería separar lo orgánico de lo inorgánico? ¿Cómo haríamos para que la gente separe lo que sale de la cocina, lo orgánico, las cáscaras de papa, de plátano, todo lo orgánico, los restos de comida, pero... separarlo del resto de la basura? Pero, ¿cómo así? O sea... O sea, ¿que yo les diga? No, no, no, ¿cómo cree usted que la gente podría hacer eso?","o":"De pronto una campaña o hacer una campaña o con proyectos que, ¿cómo se dice eso? Que inculque el...","e":"De pronto hacer una campaña, o proyectos que… ¿cómo se dice eso? Que inculquen el…","c":["EDU"],"s":null,"d":4,"k":["pedagogia"],"n":""},{"id":"A5-T26-1","p":"E04","a":"Audio5","t":205.2,"q":"Una campaña de sensibilización.","o":"Eso, eso. Para que la gente sepa y aprenda cómo tiene que hacer las separaciones de residuos.","e":"Eso. Para que la gente sepa y aprenda cómo tiene que hacer las separaciones de residuos.","c":["EDU"],"s":null,"d":4,"k":["pedagogia"],"n":""},{"id":"A5-T28-1","p":"E04","a":"Audio5","t":238.4,"q":"Muy bien. Nosotros con los de la universidad tenemos un proyecto. El proyecto consiste en tratar de que la gente separe lo orgánico para que con esos residuos orgánicos se forme compost y ese compost le sirve para los cultivos. Porque si se mezcla con el resto de la basura, vienen los perros, no sirve para nada. ¿Cree que ese proyecto es viable aquí en el barrio?","o":"Sí, claro, aquí en toda la parte del mundo, podría decir yo.","e":"Sí, claro, aquí en todo el mundo, podría decir yo.","c":["ART"],"s":null,"d":5,"k":[],"n":"viable"},{"id":"A5-T30-1","p":"E04","a":"Audio5","t":248.8,"q":"¿Qué nos recomienda? ¿Cuál debería ser el primer paso que nosotros deberíamos dar para empezar ese proyecto?","o":"No sé, pues, como de pronto hacer unos folleticos y para unos folleticos, unos, ¿cómo llaman eso?, pósteres, y que muestre cómo hacer las separaciones de residuos orgánicos e inorgánicos, o sea, como educar más a la gente, y ya, pues eso sería como lo primero.","e":"No sé, de pronto hacer unos folleticos, unos… ¿cómo llaman eso? Pósteres, que muestren cómo hacer la separación de residuos orgánicos e inorgánicos. O sea, educar más a la gente. Eso sería lo primero.","c":["EDU"],"s":null,"d":4,"k":["pedagogia"],"n":"folletos, pósteres"},{"id":"A5-T30-2","p":"E04","a":"Audio5","t":274.5,"q":"¿Qué nos recomienda? ¿Cuál debería ser el primer paso que nosotros deberíamos dar para empezar ese proyecto?","o":"Y no sé, de pronto hacer canales en YouTube, videos, en TikTok ahorita que está bastante visto, entonces más que todo por ese lado.","e":"Y de pronto hacer canales en YouTube, videos en TikTok, ahorita que está bastante visto. Más que todo por ese lado.","c":["EDU"],"s":null,"d":4,"k":["pedagogia"],"n":"TikTok, YouTube"},{"id":"A5-T32-1","p":"E04","a":"Audio5","t":308.1,"q":"¿Alguna pregunta adicional? ¿Usted cree que sería una buena solución para en especial la gente de Tihuac proponer esa caneca especial? ¿Cree que sí lo harían? Por ejemplo, si yo le doy una caneca especial a la gente para que solo ahí bote lo de la cocina.","o":"Ah, sí, claro. Sería espectacular. Porque mucha gente... ¿Qué me pagas, reina? ¿Cuántos? Ah, lo del paquetito. Sí. Ah, sí, claro. Es que... gracias. Eso es como... Eso es como si tú le regalaras a una persona un par de zapatos.","e":"Ah, sí, claro. Sería espectacular. Porque mucha gente... ¿Qué me pagas, reina? ¿Cuántos? Ah, lo del paquetito. Sí. Es que... eso es como si tú le regalaras a una persona un par de zapatos.","c":["ART","INC"],"s":null,"d":5,"k":["incentivo"],"n":"sería espectacular"},{"id":"A5-T32-2","p":"E04","a":"Audio5","t":329.5,"q":"¿Alguna pregunta adicional? ¿Usted cree que sería una buena solución para en especial la gente de Tihuac proponer esa caneca especial? ¿Cree que sí lo harían? Por ejemplo, si yo le doy una caneca especial a la gente para que solo ahí bote lo de la cocina.","o":"Yo no tengo para comprar un par de zapatos, pero si yo a ti te regalo un par de zapatos, obviamente tú te los vas a poner. Entonces es como...","e":"Yo no tengo para comprar un par de zapatos, pero si yo te regalo un par de zapatos, obviamente tú te los vas a poner. Entonces es como...","c":["INC"],"s":null,"d":4,"k":["incentivo"],"n":"zapatos regalados"},{"id":"A5-T32-3","p":"E04","a":"Audio5","t":336.1,"q":"¿Alguna pregunta adicional? ¿Usted cree que sería una buena solución para en especial la gente de Tihuac proponer esa caneca especial? ¿Cree que sí lo harían? Por ejemplo, si yo le doy una caneca especial a la gente para que solo ahí bote lo de la cocina.","o":"mucha gente de pronto no dice: \"Ah, qué pereza comprar una caneca\", o \"Ah, qué pereza comprar una caneca para hacer ese proceso, para echar los residuos\", pero si de pronto ya tú me las regalas, porque ya con unas cosas muy diferentes que le regalen a uno, ya me motivo de pronto para separar los residuos.","e":"Mucha gente de pronto dice: “Ah, qué pereza comprar una caneca para hacer ese proceso, para echar los residuos”. Pero si tú ya me las regalas, ya me motivo para separar los residuos.","c":["INC","ART"],"s":null,"d":4,"k":["incentivo"],"n":"si me la regalan, me motivo"},{"id":"A6-T14-1","p":"E05","a":"Audio6","t":59.6,"q":"Ok, listo. Normalmente, ¿qué hacen con los desechos de la papa, lo que sobra en el plato? ¿Todo va en la bolsa de red o tienen algún tipo de receta especial?","o":"No, se lo echamos a... O sea, eso le echamos a los perritos cuando quieren comer.","e":"No, se lo echamos a... Eso le echamos a los perritos cuando quieren comer.","c":["APR"],"s":null,"d":null,"k":[],"n":"sobras a los perros"},{"id":"A6-T16-1","p":"E05","a":"Audio6","t":65.1,"q":"Ah, las sobras de comida siempre a los perritos.","o":"A los perritos, sí.","e":"A los perritos, sí.","c":["APR"],"s":null,"d":null,"k":[],"n":""},{"id":"A6-T18-1","p":"E05","a":"Audio6","t":null,"q":"Ah, ok, súper bien. En el caso, digamos, de las cáscaras de huevo, ¿tienen algún tipo de manejo?","o":"Esas se las molemos y se las echamos a las matas, a las materas.","e":"Esas [cáscaras de huevo] se las molemos y se las echamos a las matas, a las materas.","c":["APR"],"s":null,"d":null,"k":[],"n":"cáscara de huevo molida a las materas"},{"id":"A6-T22-1","p":"E05","a":"Audio6","t":97.4,"q":"Y bueno, ¿consideran que este tema del chux de las basuras, si eso ha mejorado la concentración de basura, hace que sea menos el desorden?","o":"No, la gente es muy cochina. Sí, hablando lo que es, la gente es muy cochina. Porque no lo echan dentro del chux, porque el chux tenía puerta, tenía eso, pero la gente...","e":"No, la gente es muy cochina. Hablando lo que es, la gente es muy cochina, porque no lo echan dentro del shut. El shut tenía puerta, tenía todo, pero la gente…","c":["CUL","PUN"],"s":1,"d":null,"k":[],"n":"la gente es muy cochina"},{"id":"A6-T24-1","p":"E05","a":"Audio6","t":111.6,"q":"¿Hace cuánto queda el chux de ahí?","o":"Yo creo que como dos años.","e":"Creo que como dos años.","c":["PUN"],"s":null,"d":null,"k":[],"n":"el shut tiene 2 años"},{"id":"A6-T28-1","p":"E05","a":"Audio6","t":120.1,"q":"¿Y antes qué hacían cuando no había chux con las basuras?","o":"En las esquinas, pero las esquinas mantienen llenas de basura.","e":"En las esquinas, pero las esquinas mantienen llenas de basura.","c":["PUN"],"s":1,"d":null,"k":[],"n":"esquinas llenas"},{"id":"A6-T28-2","p":"E05","a":"Audio6","t":124.9,"q":"¿Y antes qué hacían cuando no había chux con las basuras?","o":"Por ejemplo, usted se va por esta cuadra y en la esquina de allá, usted se asoma y ahí le toma una foto y ve un basurero, pero una cosa impresionante, porque la basura no entra a esa cuadra, o sea, ya no recoge basura, entonces la gente viene y la bota ahí donde no pasa el carro.","e":"Por ejemplo, usted se va por esta cuadra, se asoma a la esquina de allá, le toma una foto y ve un basurero impresionante, porque el carro ya no entra a esa cuadra, ya no recoge basura, entonces la gente viene y la bota ahí, donde no pasa el carro.","c":["PUN","RUT"],"s":1,"d":null,"k":[],"n":"basurero donde no pasa el carro"},{"id":"A6-T30-1","p":"E05","a":"Audio6","t":147.6,"q":"Eso te iba a preguntar, conforme al carro de basura, ¿es puntual, pasa los días que son?","o":"Hace tres meses el carro no pasa por ahí. Por acá no pasa. Y sí toca pagar, carísimo, porque nos cobran 40 mil por la basura.","e":"Hace tres meses el carro no pasa por ahí. Por acá no pasa. Y sí toca pagar, carísimo, porque nos cobran 40 mil por la basura.","c":["RUT"],"s":1,"d":null,"k":[],"n":"3 meses sin carro, 40 mil"},{"id":"A6-T32-1","p":"E05","a":"Audio6","t":161.5,"q":"Perdón, te pregunto, ¿este cobro viene del recibo de la luz o del agua?","o":"De la luz.","e":"En la [factura] de la luz.","c":["RUT"],"s":null,"d":null,"k":[],"n":"cobro en la factura de luz"},{"id":"A6-T34-1","p":"E05","a":"Audio6","t":166.5,"q":"Ok, es mensual.","o":"Mensualmente, sí. Y vale 40, según como esto lo están cobrando o no. Pero no pasa el carro, porque yo decía que el carro pite y uno lo saca, el de la casa saca la basura, pero ni pasa, ni pasa, ni pasa, ni pasa.","e":"Mensualmente, sí. Y vale 40, según si esto lo están cobrando o no. Pero no pasa el carro, porque yo decía que el carro pite y uno lo saca, el de la casa saca la basura, pero ni pasa, ni pasa, ni pasa, ni pasa.","c":["RUT"],"s":1,"d":null,"k":[],"n":"ni pasa, ni pasa"},{"id":"A6-T38-1","p":"E05","a":"Audio6","t":196.1,"q":"Te iba a preguntar, este tema de los residuos de la comida, ¿han visto problemática con el tema de los animales? ¿Los animales rompen mucho las bolsas?","o":"Rompen, sí, y la gente, los que reciclar. Ellos rompen las bolsas y todo el reguero queda ahí.","e":"Rompen, sí, y la gente que recicla también: rompen las bolsas y todo el reguero queda ahí.","c":["ROM"],"s":1,"d":null,"k":[],"n":"recicladores rompen bolsas"},{"id":"A6-T40-1","p":"E05","a":"Audio6","t":236.3,"q":"¿Crees que si se hiciera un manejo correcto de este tema de los alimentos —ya pues no podemos hacer mucho con las botellas y eso, porque estas personas se las llevan y las solucionan, lo más que ellos no recogen como tal las cáscaras de plátano, las cáscaras de papa— crees que si desde la casa, desde cada uno de nuestros hogares, manejaramos mejor ese residuo que son los alimentos que ya se desperdiciaron, crees que se mejoraría el tema de la basura? ¿No habría tanto perro, no habría tanto olor?","o":"Sí, no habría tanto perro, sí, con eso sí, pero la gente no lo va a hacer, porque la gente es muy... o sea, hay mucha gente que es muy ignorante en ese sentido, ¿sí me entiendes? No todo el mundo. Pero, ¿qué hacemos con tres o cuatro que hagamos si diez no lo hace?","e":"Sí, no habría tanto perro, con eso sí. Pero la gente no lo va a hacer, porque hay mucha gente que es muy ignorante en ese sentido, ¿sí me entiendes? No todo el mundo. Pero, ¿qué hacemos tres o cuatro que lo hagamos si diez no lo hacen?","c":["FRE","CUL"],"s":null,"d":2,"k":[],"n":"qué hacemos 3 si 10 no"},{"id":"A6-T42-1","p":"E05","a":"Audio6","t":261.6,"q":"Correcto. Si existiera una remuneración por hacerlo, ¿usted considera que las demás personas, o bueno, todo el mundo lo haría?","o":"Yo creo que sí. Sería más factible a que no, si no la hay. Que hubiera una compensación por recoger su alimento, yo creo que sí, la gente lo haría porque... pues sabes que todo el mundo es... digamos, el tuyo que es papelería, pues no generas tanto, si no generas literalmente residuos orgánicos.","e":"Yo creo que sí. Sería más factible que no, si no la hay. Que hubiera una compensación por recoger su alimento, yo creo que sí, la gente lo haría porque... digamos, el tuyo que es papelería, pues no generas tanto, si no generas literalmente residuos orgánicos.","c":["INC"],"s":null,"d":3,"k":["incentivo"],"n":"con compensación sí"},{"id":"A6-T45-1","p":"E05","a":"Audio6","t":298.5,"q":"No sé si tú sabes, o bueno, ¿tienes algún conocimiento de si los restaurantes botan la basura ahí mismo?","o":"No tengo ni idea, pues yo me imagino que sí, ¿no? Porque para estar el chux ahí, está para todo, pues, ¿qué hago por fuera?","e":"No tengo ni idea, pero me imagino que sí, ¿no? Porque el shut está ahí para todo. ¿Qué hago por fuera?","c":["PUN"],"s":2,"d":null,"k":[],"n":""},{"id":"A6-T47-1","p":"E05","a":"Audio6","t":337.6,"q":"El tema de los olores, ¿es muy fuerte o es normal?","o":"Del tema del chux, por ejemplo, si huele mucho, pues con lo que hace tanto aire pues no se concentra, se lo lleva todo el frío y todo.","e":"El shut sí huele mucho, pero con tanto aire [el olor] no se concentra: se lo lleva el frío y todo.","c":["AMB"],"s":3,"d":null,"k":[],"n":"el viento se lleva el olor"},{"id":"A6-T49-1","p":"E05","a":"Audio6","t":347.3,"q":"¿Ayuda?","o":"Sí ayuda a no oler tanto, no es una problemática tan principal, pues el olor no.","e":"Si ayuda a no oler tanto, no es una problemática tan principal; el olor no.","c":["AMB"],"s":4,"d":null,"k":[],"n":"el olor no es lo principal"},{"id":"A6-T51-1","p":"E05","a":"Audio6","t":356.2,"q":"¿Y el tema plagas, consideras que se ve?","o":"Sí, porque hay muchas ratas y ratones, ya sean ratas, ratones... ¿Cucarachas? No, pues bueno, yo en mi casa no tengo cucarachas, no, parecen roedores sí, pero como pues hay gatitos, pues el gato los soluciona, antes me los trae, los trae como cena.","e":"Sí, porque hay muchas ratas y ratones. ¿Cucarachas? No, en mi casa no tengo cucarachas. Roedores sí, pero como hay gatitos, el gato los soluciona: me los trae como cena.","c":["FAU"],"s":2,"d":null,"k":[],"n":"ratas y ratones"},{"id":"A7-T08-1","p":"E06","a":"Audio7","t":81.4,"q":"Bueno, y venga, yo le pregunto, ¿los residuos de la basura? La basura de su casa, ¿todo va en una misma bolsa siempre?","o":"Todo, todo, todo, todo, todo. Se paga por la casa, se paga como ciento sesenta, ciento treinta mil pesos. De basura, de basura. Sí, caro. Cada piso tiene su recibo, llega su recibo. Es comercial, todo comercial. Pasa, pasa, todo.","e":"Todo, todo se paga por la casa, como ciento sesenta o ciento treinta mil pesos. De basura, sí, es caro. Cada piso tiene su recibo, llega su recibo. Es comercial, todo comercial. Pasa, pasa, todo.","c":["MEZ","RUT"],"s":2,"d":null,"k":[],"n":"recibo de 130-160 mil, \"caro\""},{"id":"A7-T10-1","p":"E06","a":"Audio7","t":119.2,"q":"Bueno, y usted que lleva tantos años viviendo acá, ¿ese problema de las basuras siempre ha estado desde que usted está?","o":"Eso, el problema de las basuras, venga, le botan ahí. Eso es fuerte al diario, que botan la basura ahí.","e":"Eso, el problema de las basuras, venga, le botan ahí. Es fuerte al diario, que botan la basura ahí.","c":["PUN"],"s":1,"d":null,"k":[],"n":"botan la basura ahí a diario"},{"id":"A7-T12-1","p":"E06","a":"Audio7","t":128.7,"q":"Pero desde que usted está aquí en el barrio, ¿siempre ha pasado eso?","o":"Claro, eso casi toda la gente, llega acá y bota.","e":"Claro, eso casi toda la gente, llega aquí y bota.","c":["PUN"],"s":2,"d":null,"k":[],"n":""},{"id":"A7-T14-1","p":"E06","a":"Audio7","t":144.6,"q":"Pero, su merced, ¿ha mejorado o ha empeorado a lo largo de los años? ¿Hay menos basura ahorita o había mucha más?","o":"Ay, no, era que primero, o sea, aquí por las calles… mejora, ¿no? Más organizado.","e":"Ay, no, es que antes, aquí por las calles… mejoró, ¿no? Está más organizado.","c":[],"s":4,"d":null,"k":[],"n":"ha mejorado, más organizado"},{"id":"A7-T16-1","p":"E06","a":"Audio7","t":168.7,"q":"Su merced, el tema de los manejos de, digamos, el arroz del día anterior, la cáscara de papa, toda esa basura, ¿ustedes la acumulan normalmente en la misma bolsa?","o":"Sí, todo. Todo va en la misma bolsa, para basura y eso.","e":"Sí, todo. Todo va en la misma bolsa, para basura y eso.","c":["MEZ"],"s":null,"d":null,"k":[],"n":""},{"id":"A7-T18-1","p":"E06","a":"Audio7","t":186.7,"q":"El tema animales, el tema perros, ¿molesta mucho la basura? ¿Los perros no rompen las bolsas ni nada de eso por el chute?","o":"No, acá no. No, nada, todo es allá, al botadero. Las bolsas las sacan de ahí al botadero.","e":"No, acá no. No, nada, todo es allá, en el botadero. Las bolsas las sacan de ahí al botadero.","c":["PUN"],"s":4,"d":null,"k":[],"n":"los perros no rompen sus bolsas"},{"id":"A7-T20-1","p":"E06","a":"Audio7","t":null,"q":"¿Usted cree que es un problema de los más graves el tema de las basuras? Los olores, el desorden. ¿Es un problema muy grave o simplemente da igual?","o":"No, pues para nosotros no, porque nosotros cogemos la basura y la llevamos y la echamos allá. Y para la comunidad, no sé, los niños… ¿Quién sabe? Nosotros no. Como yo, yo soy muy enfermo, yo no salgo a nada de aquí.","e":"No, pues para nosotros no, porque nosotros cogemos la basura y la llevamos y la echamos allá. Y para la comunidad, no sé, los niños… ¿Quién sabe? Nosotros no. Como yo, que soy muy enfermo y no salgo de aquí.","c":[],"s":4,"d":null,"k":[],"n":"para nosotros no es grave"},{"id":"A8-T06-1","p":"E07","a":"Audio8","t":70.0,"q":"Ok, cuatro años viviendo en el sector y durante esos cuatro años tú has percibido exactamente la misma problemática que has tenido acá, lo que has visto, o eso es algo muy reciente.","o":"Pues es algo que ya ha estado, pero pues con el tiempo ha avanzado un poco más, entonces se ha visto como más involucra más.","e":"Es algo que ya estaba, pero con el tiempo ha avanzado un poco más; se ha visto más.","c":["PUN"],"s":2,"d":null,"k":[],"n":"ha avanzado"},{"id":"A8-T08-1","p":"E07","a":"Audio8","t":84.1,"q":"¿Y por qué crees que ha avanzado eso desde el inicio que tú llegaste hace cuatro años al día de hoy en donde lo ves como con más frecuencia?","o":"Pues yo pienso que primeramente es por falta de cultura, o sea las personas, es \"no es basura, entonces voy y lo echo allá\". Hay muchos que, ejemplo, pues no ponen bolsas en sus canecas de basura y pues vienen y echan la basura así, pues así no sería.","e":"Yo pienso que primero es por falta de cultura: las personas piensan “es basura, entonces voy y la echo allá”. Hay muchos que no ponen bolsas en sus canecas de basura y vienen y echan la basura así, y así no debería ser.","c":["CUL","PUN"],"s":2,"d":null,"k":[],"n":""},{"id":"A8-T08-2","p":"E07","a":"Audio8","t":99.3,"q":"¿Y por qué crees que ha avanzado eso desde el inicio que tú llegaste hace cuatro años al día de hoy en donde lo ves como con más frecuencia?","o":"Entonces, principalmente, pues, sería por ese factor y también diría que porque, pues, hay muchos habitantes de calle también, o sea, no ayudan y lo que hacen es regar todo eso, los animalitos de la calle, pues, también rebuscan ahí, pues, eso es un completo desorden y, pues, afecta a todos como tal.","e":"Entonces, principalmente sería por ese factor y también diría que porque hay muchos habitantes de calle, no ayudan y lo que hacen es regar todo eso, los animalitos de la calle también rebuscan ahí, eso es un completo desorden y afecta a todos como tal.","c":["ROM","FAU"],"s":1,"d":null,"k":[],"n":"completo desorden"},{"id":"A8-T10-1","p":"E07","a":"Audio8","t":130.7,"q":"Hay tres cosas que tú tocas interesantes, entonces voy a abordar la primera. La primera tú dices falta de cultura. ¿Recuerdas en estos cuatro años que has estado acá que se hayan hecho campañas de concientización, de cultura con todos los habitantes del sector?","o":"No, mira que no, no, o sea, no. Ni la gente por sí misma toma conciencia, no es que es algo complicado.","e":"No, mira que no. Ni la gente por sí misma toma conciencia; es algo complicado.","c":["EST","CUL"],"s":2,"d":null,"k":[],"n":"nunca ha habido campañas"},{"id":"A8-T10-2","p":"E07","a":"Audio8","t":137.4,"q":"Hay tres cosas que tú tocas interesantes, entonces voy a abordar la primera. La primera tú dices falta de cultura. ¿Recuerdas en estos cuatro años que has estado acá que se hayan hecho campañas de concientización, de cultura con todos los habitantes del sector?","o":"O por ejemplo, pues, ejemplo a mí, pues, en mi casa no hay como tal algo de reciclaje, pero pues sí, con mis hermanos hemos planteado la idea y pues lo hemos ido haciendo.","e":"Por ejemplo, en mi casa no hay como tal algo de reciclaje, pero con mis hermanos hemos planteado la idea y lo hemos ido haciendo.","c":["SEP"],"s":null,"d":null,"k":[],"n":"con los hermanos"},{"id":"A8-T10-3","p":"E07","a":"Audio8","t":147.6,"q":"Hay tres cosas que tú tocas interesantes, entonces voy a abordar la primera. La primera tú dices falta de cultura. ¿Recuerdas en estos cuatro años que has estado acá que se hayan hecho campañas de concientización, de cultura con todos los habitantes del sector?","o":"Por ejemplo, hojas que ya no necesitamos, entonces como \"ay, ven, vamos a llevarlo a algún lugar que sí puedan aprovechar ese reciclaje\".","e":"Por ejemplo, hojas que ya no necesitamos, entonces como “ay, ven, vamos a llevarlo a algún lugar donde sí puedan aprovechar ese reciclaje”.","c":["SEP"],"s":null,"d":null,"k":[],"n":""},{"id":"A8-T14-1","p":"E07","a":"Audio8","t":180.2,"q":"Ok, tú mencionaste otra segunda cosa importante y que de hecho lo notamos cuando llegamos y fue la cantidad de perritos que hay. Desde el momento que tú llegaste hace cuatro años hasta el día de hoy, siempre ha sido ese comportamiento a nivel de todos los animalitos y no solo perritos, ¿has visto otro tipo de animales que han estado alrededor de todo este tema de desechos?","o":"Pues sí, ha influenciado mucho más el abandono de animalitos, entonces, pues cuando yo llegué sí se veía, pero no mucho.","e":"Sí, ha influido mucho el abandono de animalitos. Cuando yo llegué sí se veía, pero no mucho.","c":["FAU"],"s":2,"d":null,"k":[],"n":"abandono de animales"},{"id":"A8-T14-2","p":"E07","a":"Audio8","t":186.9,"q":"Ok, tú mencionaste otra segunda cosa importante y que de hecho lo notamos cuando llegamos y fue la cantidad de perritos que hay. Desde el momento que tú llegaste hace cuatro años hasta el día de hoy, siempre ha sido ese comportamiento a nivel de todos los animalitos y no solo perritos, ¿has visto otro tipo de animales que han estado alrededor de todo este tema de desechos?","o":"Yo creo que con el paso del tiempo es cuando más va avanzando, entonces, por ese lado, más animales distintos a los perritos, no, mira que gatos casi no, ellos sí son muy de casa, pero, bueno, ratas, pero eso es por la misma contaminación que sí se percibe, sí he visto, entonces...","e":"Yo creo que con el paso del tiempo es cuando más va avanzando; entonces, por ese lado, más animales distintos a los perritos, no, mira que gatos casi no, ellos sí son muy de casa, pero, bueno, ratas, pero eso es por la misma contaminación que sí se percibe, sí he visto.","c":["FAU"],"s":2,"d":null,"k":[],"n":""},{"id":"A8-T14-3","p":"E07","a":"Audio8","t":206.9,"q":"Ok, tú mencionaste otra segunda cosa importante y que de hecho lo notamos cuando llegamos y fue la cantidad de perritos que hay. Desde el momento que tú llegaste hace cuatro años hasta el día de hoy, siempre ha sido ese comportamiento a nivel de todos los animalitos y no solo perritos, ¿has visto otro tipo de animales que han estado alrededor de todo este tema de desechos?","o":"Eso nos afecta muchísimo tanto también el ambiente que eso va a nuestro sistema respiratorio y todo eso entonces. A mayor tiempo pues nos puede afectar, pero entonces...","e":"Eso nos afecta muchísimo, también el ambiente, porque eso va a nuestro sistema respiratorio. Con el tiempo nos puede afectar.","c":["AMB"],"s":1,"d":null,"k":[],"n":"sistema respiratorio"},{"id":"A8-T16-1","p":"E07","a":"Audio8","t":238.5,"q":"Y el tema de la indigencia que mencionas, que has visto bastante habitante en condición de calle, ¿cómo es el comportamiento de ellos en relación a este sector en particular, que vemos que tienes un gran problema de basuras aquí al lado? ¿Exactamente cómo es su comportamiento que hace que afecte aún más el problema?","o":"Bueno, pues principalmente ellos ingresan ahí al lugar y pues a esas bolsas que ya están hechas a desarmarlas y dejar un desorden por todo eso y a eso viene pues que van regando toda esa basura y se va expandiendo, o sea era solo la casita que se ve ahí pero ahora es todo por fuera, se puede observar la montañita allá, todo eso está lleno de basura, entonces eso influye en que ellos pues por buscar algo de comer para ellos realizan ese tipo de cosas.","e":"Principalmente ellos entran al lugar, desarman las bolsas que ya están hechas y dejan un desorden. Van regando toda esa basura y se va expandiendo: antes era solo la casita que se ve ahí, pero ahora es todo por fuera. Se puede ver la montañita allá, todo eso está lleno de basura. Ellos hacen eso por buscar algo de comer.","c":["ROM","PUN"],"s":1,"d":null,"k":[],"n":"la montañita llena de basura"},{"id":"A8-T18-1","p":"E07","a":"Audio8","t":287.1,"q":"¿Tú recuerdas si alguien conocido, tú o acá la persona encargada de este comercio, haya puesto algún tipo de denuncia, algún derecho de petición o algo ante los entes reguladores o el mismo distrito con el problema que ustedes tienen?","o":"Sí, claro, sí, varias personas ya lo han hecho la petición, pero aún así no se ha sido escuchado de manera como deberíamos ser escuchados, como quisiéramos escuchar. Entonces, pues sí se han hecho, pero pues no se ha actuado de manera que nosotros nos gustaría que actuara.","e":"Sí, claro, varias personas ya lo han hecho la petición, pero aún así no se ha sido escuchados de la manera en que deberíamos ser escuchados, como quisiéramos. Entonces, sí se han hecho, pero no se ha actuado de la manera que nos gustaría que actuara.","c":["EST"],"s":1,"d":null,"k":[],"n":"peticiones no escuchadas"},{"id":"A8-T20-1","p":"E07","a":"Audio8","t":312.9,"q":"¿A ti cómo te gustaría que se solucionara el problema? Si tú tuvieses la oportunidad de proponer una solución y decir, esto lo deberían hacer, ¿qué crees que debería ser la solución?","o":"Primordial pues una campaña, sería súper importante concientizar porque pues primero empieza desde nosotros, desde casa puede empezar y pues así mismo en la regular pues las basuras, ejemplo pues hay mucho... mucho tema pues que no es basura pero si se puede utilizar, reutilizar, entonces eso sería un buen mecanismo para plantear.","e":"Primordial una campaña. Sería súper importante concientizar, porque primero empieza desde nosotros, desde la casa, y así mismo en el manejo de las basuras. Hay mucho material que no es basura, sino que se puede utilizar, reutilizar. Eso sería un buen mecanismo para plantear.","c":["EDU"],"s":null,"d":4,"k":["pedagogia"],"n":"empieza desde casa"},{"id":"A8-T22-1","p":"E07","a":"Audio8","t":367.0,"q":"Ok, desde la casa tú mencionas que estabas o con tus hermanos hacías un poco iniciativas a nivel de reciclaje. Si nos vamos exactamente al tema de los desechos orgánicos en la cocina, en tu hogar, ¿cómo hacen ustedes el manejo de lo típico, la cáscara de huevo que queda después de hacer el desayuno, la cáscara de banano y todo este tipo de desechos orgánicos incluso que quedan en el plato después? ¿Qué pasa con eso a nivel del hogar?","o":"Bueno, pues eso sí, o lo consideramos o quizás no tengamos el conocimiento, pues sí es algo orgánico, pero entonces sí lo botamos, sí lo desperdiciamos y pues va a la basura.","e":"Bueno, o lo consideramos o quizás no tengamos el conocimiento, es algo orgánico, entonces lo botamos, lo desperdiciamos y va a la basura.","c":["MEZ"],"s":null,"d":null,"k":[],"n":"lo orgánico se desperdicia"},{"id":"A8-T24-1","p":"E07","a":"Audio8","t":385.2,"q":"¿Tienen un mismo chute de basura para todo o separan?","o":"Separamos lo que digamos es plástico y hojas y ya lo orgánico de cocina pues queda solo en la cocina, la basura de la cocina.","e":"Separamos lo que es plástico y hojas, y lo orgánico de la cocina queda en la cocina, en la basura de la cocina.","c":["SEP","MEZ"],"s":null,"d":null,"k":[],"n":""},{"id":"A8-T26-1","p":"E07","a":"Audio8","t":404.6,"q":"Lo orgánico de cocina va junto con, no sé, con más basura aparte del plástico, el plástico y el papel lo separan, pero todo lo demás va en el mismo chute.","o":"Diría pues lo orgánico, porque por ejemplo esos plastiquitos de dulces o cosas así va con lo plástico y papel que ya mencioné anteriormente.","e":"Diría que lo orgánico, porque los plastiquitos de dulces y cosas así van con el plástico y el papel que ya mencioné.","c":["SEP"],"s":null,"d":null,"k":[],"n":""},{"id":"A8-T28-1","p":"E07","a":"Audio8","t":415.8,"q":"¿Cada cuánto pasa acá la basura?","o":"Cada día, día de por medio pasa. O sea, no es muy demorada tampoco, o sea, pasa.","e":"Cada día, día de por medio pasa. No es muy demorada tampoco.","c":["RUT"],"s":4,"d":null,"k":[],"n":"el carro pasa día de por medio"},{"id":"A8-T30-1","p":"E07","a":"Audio8","t":446.8,"q":"¿Y el comportamiento que tienes tú, incluso que has visto tus vecinos en relación al paso de la basura, la dejan en qué lugar? ¿O cómo hacen para dejar los desechos, específicamente los desechos orgánicos? ¿Los mantienen en su hogar mientras llega la basura, los sacan después de que llegue la basura, en el momento que llegue la basura? ¿O cómo funciona ese tema del camino desde la cocina hasta ese carro?","o":"Bueno, pues se ha evidenciado varias veces que es mucho antes, una noche antes sacan la basura, entonces se ve mucho el reguero de basura y ahí es donde aprovechan los animalitos a hacer su desorden, entonces al día siguiente se ve mucho desorden, aunque pues las personas que son encargadas de recoger la basura intentan limpiar y dejar eso lo más prudente, pero pues aún así no es suficiente porque pues también aquí un factor es el viento entonces eso corre muchísimo la basura entonces eso llega hasta nuestras caras que es algo pues incómodo y ya.","e":"Se ha visto varias veces que sacan la basura mucho antes, una noche antes. Entonces se ve mucho reguero y ahí es donde los animalitos aprovechan para hacer su desorden; al día siguiente se ve mucho desorden. Las personas encargadas de recoger la basura intentan limpiar y dejar eso lo mejor posible, pero no es suficiente, porque aquí otro factor es el viento: corre muchísimo la basura y nos llega hasta la cara, lo cual es incómodo.","c":["PUN","ROM","AMB"],"s":1,"d":null,"k":[],"n":"la noche antes; viento a la cara"},{"id":"A8-T32-1","p":"E07","a":"Audio8","t":521.3,"q":"Ok, una última pregunta ya para finalizar y es el tema del espacio en este sector a nivel de los hogares. El tipo de elemento que utilizan para recoger este tipo de desechos orgánicos, ¿qué tipo de caja o qué tipo de... cómo se llamaría esto? ¿Cierto? Como qué tipo de... sí, no sé cómo decirle, como dónde se deposita, o qué tipo de elemento utilizan, ¿la bolsa ahí en el piso, utilizan una caneca más o menos de qué tamaño suelen utilizar? Todo este tipo de cosas para ustedes, tanto en el comercio como también en tu hogar.","o":"Bolsitas de basura bien cerradas y se deja y pues no sea, es que hay puntos específicos donde se puede dejar la basura que son como una casita así donde se ve, pues acá hay uno y en la parte de arriba bien arriba hay otro, pero entonces todas estas personas de esquinas las dejan ahí en la esquina, entonces pues eso no está bien porque ahí es por donde se empieza, entonces sí no deberían llevar la puesta a los puntos que ya integrados.","e":"Bolsitas de basura bien cerradas, y se dejan. Hay puntos específicos donde se puede dejar la basura, como una casita: acá hay uno y en la parte de arriba hay otro. Pero muchas personas las dejan ahí en la esquina, y eso no está bien, porque ahí es donde empieza. Deberían llevarlas a los puntos que ya están destinados.","c":["PUN"],"s":2,"d":null,"k":[],"n":""},{"id":"A8-T32-2","p":"E07","a":"Audio8","t":544.7,"q":"Ok, una última pregunta ya para finalizar y es el tema del espacio en este sector a nivel de los hogares. El tipo de elemento que utilizan para recoger este tipo de desechos orgánicos, ¿qué tipo de caja o qué tipo de... cómo se llamaría esto? ¿Cierto? Como qué tipo de... sí, no sé cómo decirle, como dónde se deposita, o qué tipo de elemento utilizan, ¿la bolsa ahí en el piso, utilizan una caneca más o menos de qué tamaño suelen utilizar? Todo este tipo de cosas para ustedes, tanto en el comercio como también en tu hogar.","o":"Entonces sí, la mayoría de veces solo es en bolsitas bien cerradas y pues como ya dije principalmente, pues a veces hay personas también que ni siquiera bulsan, entonces solo llevan la caneca de su basura, la echan y ya, porque sí lo he evidenciado y pues sí lo he visto.","e":"Entonces sí, la mayoría de las veces solo es en bolsitas bien cerradas y como ya dije principalmente, a veces hay personas también que ni siquiera bulsan, entonces solo llevan la caneca de su basura, la echan y ya, porque lo he evidenciado y visto.","c":["PUN"],"s":2,"d":null,"k":[],"n":"ni siquiera embolsan"},{"id":"A9-T09-1","p":"E08","a":"Audio9","t":68.8,"q":"En el sentido de todo el tema de contaminación y desechos orgánicos.","o":"Pues la verdad, por ejemplo, pues acá la basura pasa, pero pasa es como, o sea, ¿cómo le diría yo? Pasa es de afán.","e":"La verdad, acá la basura pasa, pero pasa como… ¿cómo le diría yo? Pasa de afán.","c":["RUT"],"s":2,"d":null,"k":[],"n":"pasa de afán"},{"id":"A9-T11-1","p":"E08","a":"Audio9","t":74.0,"q":"Ah, ok.","o":"¿Sí? O sea, no hay, sí, en sí, en sí, no, no, por ejemplo, digamos, no paran en cierto lugar, que de pronto digan: \"bueno, mire\", o que diga uno: \"uy, pasó el carro, toca sacar la basura\". No, si no pasan es de afán. Eso por un lado.","e":"¿Sí? No hay, en sí, no paran en cierto lugar, que de pronto digan: “bueno, mire”, o uno diga: “uy, pasó el carro, toca sacar la basura”. Si no pasan es de afán. Eso por un lado.","c":["RUT"],"s":2,"d":null,"k":[],"n":""},{"id":"A9-T11-2","p":"E08","a":"Audio9","t":88.4,"q":"Ah, ok.","o":"Por el otro, pues a como a tres cuadras más o menos, pues hay un sitio donde se puede dejar la basura, pero de igual, la misma vaina, porque, o sea, de allá pues vienen, si me entiende, pues digamos así, la gente y escarban y, bueno, y si me entiende, sacan papeles, se van al viento, los perros.","e":"Por el otro [lado], a unas tres cuadras hay un sitio donde se puede dejar la basura, pero igual es la misma vaina: de allá vienen, la gente escarba, saca papeles, se van al viento, los perros…","c":["PUN","ROM","AMB"],"s":2,"d":null,"k":[],"n":""},{"id":"A9-T11-3","p":"E08","a":"Audio9","t":109.2,"q":"Ah, ok.","o":"Entonces, todo eso lo traen otra vez para, si me entiende, para la zona. Entonces, pues de igual, pues, o sea, está como, o seja, sí es bueno ese chux, pero al mismo tiempo, pues no, porque no, no se beneficia uno en nada.","e":"Entonces todo eso lo traen otra vez para la zona. Sí es bueno ese shut, pero al mismo tiempo no, porque uno no se beneficia en nada.","c":["PUN"],"s":2,"d":null,"k":[],"n":"no se beneficia uno en nada"},{"id":"A9-T11-4","p":"E08","a":"Audio9","t":123.5,"q":"Ah, ok.","o":"Y sí llegan malos olores, ve uno, sí, animales, o sea, animalitos, ratas, bueno, sí, de todo lo que sea.","e":"Y cuando llegan malos olores, es porque hay animales, ratas, de todo lo que sea.","c":["AMB","FAU"],"s":2,"d":null,"k":[],"n":""},{"id":"A9-T13-1","p":"E08","a":"Audio9","t":135.8,"q":"Cuando tú llegaste a este sector hace 5 años al día de hoy, ¿la situación cambió o siempre ha sido así?","o":"No, siempre ha sido así, siempre ha sido así.","e":"No, siempre ha sido así.","c":["PUN"],"s":2,"d":null,"k":[],"n":"siempre ha sido así"},{"id":"A9-T16-1","p":"E08","a":"Audio9","t":152.5,"q":"Tú hablabas algo interesante, y es en relación a que acá el sistema de aseo y, bueno, todo el tema de las basuras pasa cuando se le de la gana, o has notado que tiene cierta periodicidad?","o":"No, pues más que todo, pues se supone que, digamos, o sea, por ejemplo, digamos, tiene que pasar los lunes, los miércoles y los sábados. Hoy, por ejemplo, es sábado y no he visto ni siquiera el carro por ahí.","e":"Se supone que tiene que pasar los lunes, los miércoles y los sábados. Hoy, por ejemplo, es sábado y no he visto ni siquiera el carro por ahí.","c":["RUT"],"s":1,"d":null,"k":[],"n":"sábado sin carro"},{"id":"A9-T19-1","p":"E08","a":"Audio9","t":181.3,"q":"¿Cómo funciona la recolección de todo el tema de desechos orgánicos en un local como este? ¿Cuál es el protocolo, cómo la Secretaría [de Salud/Educación] exige algo en particular a nivel de manejo de desechos orgánicos en un local como este?","o":"Sí, claro, sí señor. Sí, ellos le dicen a uno, por ejemplo, digamos: \"mire, hay canecas ahí\", y uno tiene una caneca allá y, por ejemplo, digamos, bota uno lo que es así basura, por ejemplo, digamos, papeles, bueno, así, cositas así.","e":"Sí, claro, sí señor. Sí, ellos le dicen a uno, por ejemplo: \"mire, hay canecas ahí\", y uno tiene una caneca allá y bota lo que es basura, papeles, así, cositas así.","c":["SEP"],"s":null,"d":null,"k":[],"n":""},{"id":"A9-T19-2","p":"E08","a":"Audio9","t":193.3,"q":"¿Cómo funciona la recolección de todo el tema de desechos orgánicos en un local como este? ¿Cuál es el protocolo, cómo la Secretaría [de Salud/Educación] exige algo en particular a nivel de manejo de desechos orgánicos en un local como este?","o":"Y tiene uno otra caneca donde, por ejemplo, digamos, recicla, digamos, todo lo que sea de plástico, digámoslo así.","e":"Y tiene uno otra caneca donde recicla todo lo que sea de plástico, digámoslo así.","c":["SEP"],"s":null,"d":null,"k":[],"n":""},{"id":"A9-T26-1","p":"E08","a":"Audio9","t":259.1,"q":"¿No importaría, por ejemplo, llegar con una cáscara de banano y botarla ahí?","o":"No. O sea, por ejemplo, digamos, sí, o sea, si llegan y la botan ahí, pues la botan ahí. Pero de igual, o sea, por ejemplo, igual uno, pues, o sea, nosotros tenemos una chica acá.","e":"No. Si llegan y la botan ahí, pues la botan ahí. Pero nosotros tenemos una chica acá.","c":["MEZ"],"s":null,"d":null,"k":[],"n":""},{"id":"A9-T28-1","p":"E08","a":"Audio9","t":267.0,"q":"Ok.","o":"Y ella es la que hace el aseo, tal. Entonces uno le dice: \"bueno, si de pronto hay allá frascos o algo, échelos acá y el resto, lo que es basura, pues déjelo allá\". Perfecto.","e":"Ella es la que hace el aseo. Entonces uno le dice: “Si hay allá frascos o algo, échelos acá, y el resto, lo que es basura, déjelo allá”.","c":["SEP"],"s":null,"d":null,"k":[],"n":""},{"id":"A9-T30-1","p":"E08","a":"Audio9","t":288.9,"q":"¿Cómo ve el sector a nivel de qué tanto le afecta, por ejemplo, el hecho de todos los animalitos que están en el sector? Hemos visto muchísimo perrito por toda la calle. ¿A qué cree que se debe eso particularmente?","o":"Pues hoy en día, prácticamente, pues la gente tiene, qué le diría yo, como más prioridad con los perros, digámoslo así, ¿sí? Que una persona. Entonces, pues hay muchas personas que tienen esos perros, o sea, los tienen y al mismo tiempo no los tienen porque los tienen abandonados.","e":"Hoy en día la gente tiene más prioridad con los perros que con una persona. Hay muchas personas que tienen perros, pero los tienen y al mismo tiempo no los tienen, porque los tienen abandonados.","c":["FAU"],"s":2,"d":null,"k":[],"n":"perros abandonados"},{"id":"A9-T30-2","p":"E08","a":"Audio9","t":304.3,"q":"¿Cómo ve el sector a nivel de qué tanto le afecta, por ejemplo, el hecho de todos los animalitos que están en el sector? Hemos visto muchísimo perrito por toda la calle. ¿A qué cree que se debe eso particularmente?","o":"Entonces de igual uno sí ve mucho perro en la calle. Bastante.","e":"Entonces uno sí ve mucho perro en la calle. Bastante.","c":["FAU"],"s":2,"d":null,"k":[],"n":""},{"id":"A9-T35-1","p":"E08","a":"Audio9","t":353.2,"q":"Tú mencionaste algo en relación al problema que tenía este sector con los chux que quedan aquí a pocas cuadras, de hecho. Sí, señor. En relación a ese problema, ¿recuerdas durante estos 5 años que se haya hecho alguna solicitud oficial, que hayan venido, que hayan hecho alguna campaña o algo en relación para solucionar? ¿Han propuesto alguna solución?","o":"No, no señor. ¿Han...? Hasta donde yo sepa, no.","e":"No, no señor. Hasta donde yo sé, no.","c":["EST"],"s":2,"d":null,"k":[],"n":"nunca hubo campaña"},{"id":"A9-T37-1","p":"E08","a":"Audio9","t":361.5,"q":"¿Y recuerda que de pronto la comunidad se haya unido para hacer solicitudes?","o":"No, tampoco.","e":"No, tampoco.","c":["FRE"],"s":2,"d":null,"k":[],"n":"la comunidad no se ha unido"},{"id":"A9-T39-1","p":"E08","a":"Audio9","t":381.6,"q":"Ok. Hasta este momento, ese problema que ustedes están presentando en el sector, no ha habido como una conciliación con toda la comunidad, tanto de comercios como de viviendas, para decir: \"pasemos esto a la superintendencia, no sé, o al tema de alcantarillado, o al ente regulador\"?","o":"No, no señor. Perfecto.","e":"No, señor. Perfecto.","c":["FRE"],"s":2,"d":null,"k":[],"n":""},{"id":"A9-T41-1","p":"E08","a":"Audio9","t":395.8,"q":"Ahora, mencionabas algo relacionado con el paso de las basuras, y me voy a devolver un poquito nuevamente a ese tema, y es que, ¿cuál es la diferencia entre el paso de las basuras en este sector en relación al sector donde tú vives?","o":"Bueno, lo que pasa es que, por ejemplo, digamos, acá donde tiene uno el negocio, pues es comercial. Y, pues, donde yo vivo, pues es residencial. Allá sí pasa la basura. Eso sí, por ejemplo, digamos, pasa lo que es el lunes, el miércoles y el viernes. Esos tres días sí pasa. ¿Para qué?","e":"Bueno, lo que pasa es que acá donde tiene uno el negocio es comercial. Y donde yo vivo es residencial. Allá sí pasa la basura. Eso sí, los lunes, miércoles y viernes pasa. Esos tres días sí pasa. ¿Para qué?","c":["RUT"],"s":2,"d":null,"k":[],"n":"en la zona residencial sí pasa"},{"id":"A9-T41-2","p":"E08","a":"Audio9","t":417.9,"q":"Ahora, mencionabas algo relacionado con el paso de las basuras, y me voy a devolver un poquito nuevamente a ese tema, y es que, ¿cuál es la diferencia entre el paso de las basuras en este sector en relación al sector donde tú vives?","o":"Y pasa cumplido.","e":"Y pasa cumplido.","c":["RUT"],"s":null,"d":null,"k":[],"n":""},{"id":"A9-T43-1","p":"E08","a":"Audio9","t":419.9,"q":"¿Y pasa cumplido?","o":"Y hasta pitan y todo. O sea, como tiene que ser, digámoslo así. Pero acá no. Y se supone que acá es comercio, pues es donde antes colmaba verano, ¿no? Claro. Pero eso sí, llega Navidad, entonces ahí sí pasan los que supuestamente barren por ahí: \"ay, vecino, que la Navidad, que no sé qué\".","e":"Y hasta pitan y todo. Como tiene que ser. Pero acá no. Se supone que acá es comercio, donde antes colmaba verano, ¿no? Claro. Pero llega Navidad, entonces ahí sí pasan los que supuestamente barren por ahí: \"ay, vecino, que la Navidad, que no sé qué\".","c":["RUT"],"s":1,"d":null,"k":[],"n":"aparecen en Navidad"},{"id":"A9-T43-2","p":"E08","a":"Audio9","t":436.0,"q":"¿Y pasa cumplido?","o":"Pues dígame uno cómo les da la Navidad si no se lo han ganado, digámoslo así. Ok.","e":"Dígame cómo les da uno la Navidad si no se la han ganado.","c":["RUT"],"s":1,"d":null,"k":[],"n":""},{"id":"A9-T45-1","p":"E08","a":"Audio9","t":444.2,"q":"La empresa que recoge la basura acá es la misma, o sea, ¿esa basura qué empresa? ¿O recuerdas el nombre de la empresa que la recoge?","o":"Sí, Lime, la misma.","e":"Sí, Líme, la misma.","c":["RUT"],"s":null,"d":null,"k":[],"n":""},{"id":"A9-T49-1","p":"E08","a":"Audio9","t":469.2,"q":"Dale, perfecto. Ahora, otra pregunta: en tu casa, ¿cómo funciona el tema de la recolección de basura? Cuando terminas de desayunar, o todo el tema de cáscaras y cosas así, ¿tú tienes un chux especial para botar eso, o es lo mismo con toda la otra?","o":"No, yo la verdad, en la casa, pues como, o sea, en mi casa tengo un jardín, en la parte de atrás. Entonces, ¿qué es lo que pasa? Que, por ejemplo, digamos, las vainitas esas de los huevos y toda esa vaina, pues yo las recolecto, yo las dejo en una bolsita.","e":"La verdad, en mi casa tengo un jardín en la parte de atrás. Entonces, las cascaritas de los huevos y todo eso yo las recolecto y las dejo en una bolsita.","c":["APR"],"s":null,"d":null,"k":[],"n":"guarda las cáscaras de huevo"},{"id":"A9-T49-2","p":"E08","a":"Audio9","t":482.7,"q":"Dale, perfecto. Ahora, otra pregunta: en tu casa, ¿cómo funciona el tema de la recolección de basura? Cuando terminas de desayunar, o todo el tema de cáscaras y cosas así, ¿tú tienes un chux especial para botar eso, o es lo mismo con toda la otra?","o":"Y cuando ya tengo así de articas, entonces llego y las cojo con, o sea, así con las manos, le hago así, y se la echo a las maticas, como abono.","e":"Y cuando ya tengo así de articas, entonces llego y las cojo con las manos, les hago así, y se la echo a las maticas, como abono.","c":["APR","AGR"],"s":null,"d":null,"k":[],"n":"a las maticas como abono"},{"id":"A9-T51-1","p":"E08","a":"Audio9","t":491.4,"q":"Ok. ¿Y el resto de desechos?","o":"El resto ya, por ejemplo, digamos así que se tome uno una gaseosa, o bueno, así que bote uno los frascos del aceite, bueno, así.","e":"El resto ya, por ejemplo, cuando uno se toma una gaseosa o bota los frascos del aceite…","c":["SEP"],"s":null,"d":null,"k":[],"n":""},{"id":"A9-T51-2","p":"E08","a":"Audio9","t":500.5,"q":"Ok. ¿Y el resto de desechos?","o":"Eso sí los deja uno en una bolsa aparte, y cuando pasa la basura, entonces ahí ese talego es donde está todo lo que es de plástico, y ya el resto, ya en bolsa, ya pues lo que son papeles del baño, lo que es de la cocina, etcétera, etcétera.","e":"Eso sí los deja uno en una bolsa aparte, y cuando pasa la basura, ahí ese talego es donde está todo lo que es de plástico, y ya el resto, ya lo que son papeles del baño, lo que es de la cocina, etcétera.","c":["SEP","MEZ"],"s":null,"d":null,"k":[],"n":"plástico aparte; lo de la cocina con lo del baño"},{"id":"A9-T53-1","p":"E08","a":"Audio9","t":534.3,"q":"Perfecto. Hablabas de tu huerta, de lo que tienes ahí en tu patio. ¿Sueles utilizar algún tipo de abono o cosas para poder que las matas crezcan mejor, para que todo tu jardín sea mejor? O compras por aparte tipo de abono, fertilizante, o cómo funciona el tema de tu huerta?","o":"No, pues yo sí compro, o sea, fertilizantes, y les echo a las maticas.","e":"No, yo sí compro fertilizantes y les echo a las maticas.","c":["AGR"],"s":null,"d":null,"k":[],"n":"compra fertilizantes"},{"id":"A9-T55-1","p":"E08","a":"Audio9","t":543.6,"q":"Ok. ¿Fertilizantes de alguna marca en especial, algo que tiene su mente?","o":"No, o sea, eso es como que como para que les dé como vida, que como que se pongan más bonitas. ¿Sí? Algo así.","e":"No, eso es como para que les dé vida, que se pongan más bonitas. ¿Sí? Algo así.","c":["AGR"],"s":null,"d":null,"k":[],"n":""},{"id":"A9-T57-1","p":"E08","a":"Audio9","t":576.4,"q":"Listo. Ahora, otra duda ya para finalizar. Con el problema de basuras que se tiene, si yo te preguntara: ¿qué idea o qué solución a ti se te ocurriría como para solucionar ese tema? O de tu experiencia estos 5 años que has tenido acá en el sector, ¿cuál crees que sea una solución viable que pueda unir a la comunidad?","o":"Pues yo digo que, o sea, para mí, pues deberían era ser como, pues más que todo esto es como ya es como la alcaldía, ¿no?","e":"Para mí, esto ya es como un tema de la alcaldía, ¿no?","c":["EST"],"s":null,"d":3,"k":[],"n":""},{"id":"A9-T57-2","p":"E08","a":"Audio9","t":null,"q":"Listo. Ahora, otra duda ya para finalizar. Con el problema de basuras que se tiene, si yo te preguntara: ¿qué idea o qué solución a ti se te ocurriría como para solucionar ese tema? O de tu experiencia estos 5 años que has tenido acá en el sector, ¿cuál crees que sea una solución viable que pueda unir a la comunidad?","o":"Si me entiende, que como que, o sea, que pongan, si me entiende, su mano en el corazón y diga: \"bueno, hombre, ¿qué es lo que está pasando en los barrios? Vamos a mirar a ver qué vamos a hacer\". ¿Sí?","e":"Que pongan la mano en el corazón y digan: “Bueno, hombre, ¿qué es lo que está pasando en los barrios? Vamos a mirar qué vamos a hacer”.","c":["EST"],"s":2,"d":3,"k":[],"n":"que la alcaldía ponga la mano en el corazón"},{"id":"A9-T57-3","p":"E08","a":"Audio9","t":595.6,"q":"Listo. Ahora, otra duda ya para finalizar. Con el problema de basuras que se tiene, si yo te preguntara: ¿qué idea o qué solución a ti se te ocurriría como para solucionar ese tema? O de tu experiencia estos 5 años que has tenido acá en el sector, ¿cuál crees que sea una solución viable que pueda unir a la comunidad?","o":"Y hacer como una asamblea, como llamar a la gente, como decirles: \"bueno, vamos a hacer esto, vamos a hacer aquello, ustedes qué opinan? Si están de acuerdo, no están de acuerdo, qué necesitan, qué podemos hacer por ustedes\". Algo así, ¿sí?","e":"Y hacer como una asamblea, llamar a la gente y decirles: “bueno, vamos a hacer esto, vamos a hacer aquello, ustedes qué opinan? Si están de acuerdo, si no están de acuerdo, qué necesitan, qué podemos hacer por ustedes”. Algo así, ¿sí?","c":["COM","EST"],"s":null,"d":4,"k":["lideres"],"n":"asamblea con la gente"},{"id":"A9-T59-1","p":"E08","a":"Audio9","t":610.0,"q":"¿Nunca han venido?","o":"Pero no, o sea, no. O sea, el tiempo que yo llevo acá, no.","e":"Pero no, el tiempo que yo llevo acá, no.","c":["EST"],"s":1,"d":null,"k":[],"n":"nunca han venido"},{"id":"A9-T61-1","p":"E08","a":"Audio9","t":619.0,"q":"¿Y hay algún líder entre los vecinos, entre el sector, que usted conozca, que tú conozcas?","o":"No, la verdad no. No, así que de pronto alguien que uno diga de pronto alguien así, un líder, o de pronto digamos que un concejal, o un edil, algo así, digámoslo así, no.","e":"No, la verdad no. Alguien que uno diga que es un líder, o un concejal, o un edil, no.","c":["COM"],"s":2,"d":null,"k":[],"n":"no conoce líderes"},{"id":"A9-T63-1","p":"E08","a":"Audio9","t":646.7,"q":"Ok. ¿Y el sector de la esquina, alguna vez lo has visto medianamente limpio? De, o sea, en el resto, o sea, en el... en el, en el, todo este sector, y más que todo donde en el chux de la esquina, ¿alguna vez has visto menos basura ahí? ¿O siempre está?","o":"No, siempre, siempre es lo mismo. Y cuando, por ejemplo, digamos así que esté lloviendo, que esté haciendo mucho viento, y toda esa vaina, eso todos los papeles vienen para acá.","e":"No, siempre es lo mismo. Y cuando está lloviendo o haciendo mucho viento, todos los papeles vienen para acá.","c":["PUN","AMB"],"s":1,"d":null,"k":[],"n":"siempre es lo mismo"},{"id":"A9-T65-1","p":"E08","a":"Audio9","t":657.3,"q":"¿Y cómo te afecta el olor? ¿Llega hasta acá el olor?","o":"No, pues, o sea, digamos que llegue olor, olor no. O sea, más que todo es fastidioso porque, por ejemplo, digamos, llegan todos los papeles y hace un remolino y se meten todos los papeles. Y sí, le ensucia uno las neveras, bueno, en fin. Eso es lo feo. Eso por un lado.","e":"No, olor no llega. Más que todo es fastidioso porque llegan todos los papeles, hace un remolino y se meten todos los papeles. Y sí, le ensucian a uno las neveras. Eso es lo feo.","c":["AMB"],"s":2,"d":null,"k":[],"n":"papeles en las neveras"},{"id":"A9-T65-2","p":"E08","a":"Audio9","t":673.0,"q":"¿Y cómo te afecta el olor? ¿Llega hasta acá el olor?","o":"Por el otro, cuando llueve, se forma, si me entiende, o sea, como pichal, digámoslo así. Eso es como, por ejemplo, digamos ahí al frente. Si usted se pone a mirar de acá al otro lado, ¿sí? Todo está destapado, todo está en tierra. ¿Sí me entiende?","e":"Por otro lado, cuando llueve se forma como un pichal. Por ejemplo, ahí al frente: si usted mira de acá al otro lado, todo está destapado, todo está en tierra.","c":["AMB"],"s":2,"d":null,"k":[],"n":"pichal cuando llueve"},{"id":"A9-T65-3","p":"E08","a":"Audio9","t":688.9,"q":"¿Y cómo te afecta el olor? ¿Llega hasta acá el olor?","o":"Y no, o sea, nadie tampoco dice nada, nadie hace nada, de pronto decir: \"bueno, hombre, que al menos que nos echen un asfalto ahí\", como para que, si me entiende, nada. Pero no.","e":"Y no, nadie tampoco dice nada, nadie hace nada, de pronto decir: “bueno, hombre, que al menos que nos echen un asfalto ahí”, como para que, nada. Pero no.","c":["EST","FRE"],"s":1,"d":null,"k":[],"n":"nadie hace nada"},{"id":"A9-T67-1","p":"E08","a":"Audio9","t":704.1,"q":"¿Ya usted cree que los vecinos ya normalizaron ese lugar y viven tranquilos con eso?","o":"No. Pues yo digo que de pronto no. O sea, pues de que vivan felices, no. Yo creo que ya como que se acostumbran, más bien, digámoslo así. Que ya dirán: \"ah, pues las cosas están así, pues dejémoslas así\".","e":"No. Yo digo que de pronto no. De que vivan felices, no. Creo que ya se acostumbran, más bien. Dirán: \"ah, pues las cosas están así, dejémoslas así\".","c":["FRE","CUL"],"s":2,"d":null,"k":[],"n":"se acostumbran"},{"id":"A9-T71-1","p":"E08","a":"Audio9","t":751.1,"q":"Una última pregunta ya para finalizar, y es: ¿la basura, usted cree que tiene alguna relación o percepción con la seguridad del sector?","o":"Pues de pronto, pues yo digo que no, no tiene ninguna seguridad, porque... O relación. Digamos que de pronto, pues viene de pronto, qué sé yo, pues como saben que hay un chux allá y la gente todo lo bota allá, pues pueden venir gente de otros lados, ¿sí me entiende?","e":"Yo digo que no tiene relación. Aunque, como saben que hay un shut allá y la gente todo lo bota allá, puede venir gente de otros lados, ¿sí me entiende?","c":["SEG","PUN"],"s":2,"d":null,"k":[],"n":""},{"id":"A9-T71-2","p":"E08","a":"Audio9","t":768.9,"q":"Una última pregunta ya para finalizar, y es: ¿la basura, usted cree que tiene alguna relación o percepción con la seguridad del sector?","o":"Y pueden venir ahí a escarbar. Pero entonces, pueden que escarben, pero entonces están también mirando, ¿sí? O sea, digamos, las tiendas, para decir: \"bueno, de pronto en X parte dejan solo, pues por qué no hacemos tal cosa\", ¿sí? Entonces se puede prestar también para muchas cosas.","e":"Y pueden venir ahí a escarbar. Pero entonces, pueden que escarben, pero están también mirando, ¿sí? Las tiendas, para decir: “bueno, de pronto en X parte dejan solo, por qué no hacemos tal cosa”, ¿sí? Entonces se puede prestar también para muchas cosas.","c":["SEG"],"s":2,"d":null,"k":[],"n":"escarban pero miran las tiendas"},{"id":"A9-T73-1","p":"E08","a":"Audio9","t":181.6,"q":"Ok. Entonces sí es también como una atracción a nivel de delincuencia, puede atraer.","o":"Sí, claro. Sí, señor.","e":"Sí, claro. Sí, señor.","c":["SEG"],"s":null,"d":null,"k":[],"n":""},{"id":"A10-T02-1","p":"E05","a":"Audio10","t":null,"q":"¿Y el abono es carísimo?","o":"Sí.","e":"Sí.","c":["AGR"],"s":null,"d":null,"k":[],"n":"abono carísimo"},{"id":"A10-T04-1","p":"E05","a":"Audio10","t":5.0,"q":"¿El abono es carísimo y el abono natural es diez veces mejor?","o":"Mejor que todos esos químicos que hay. Porque el abono en Colombia se importa. El abono en Colombia se trae de otro país, entonces empezar desde abajo.","e":"Mejor que todos esos químicos que hay. Porque el abono en Colombia se importa. El abono en Colombia se trae de otro país, entonces hay que empezar desde abajo.","c":["AGR"],"s":null,"d":null,"k":[],"n":"abono importado"},{"id":"A10-T06-1","p":"E05","a":"Audio10","t":13.0,"q":"¿Empezar desde abajo?","o":"Sí, porque en el campo, por ejemplo, yo cuando voy al campo a visitar a los familiares de mi esposo, ellos todo reciclan. Lo que es los hollejos, todo eso lo cogen. El café, todo eso. Todo, para todo.","e":"Sí, porque en el campo, por ejemplo, cuando voy a visitar a los familiares de mi esposo, ellos todo lo reciclan: los hollejos, todo eso lo cogen; el café, todo. Para todo.","c":["AGR"],"s":null,"d":null,"k":[],"n":"en el campo todo se recicla (familiares)"}]};
